// Annotate selection modal
function showAnnotateSelectionModal(tabState, lo, hi, onApply, onClose) {
  const allowableLength = hi - lo + 1;
  const overlay = document.createElement("div");
  overlay.className = "modal-overlay";
  const box = document.createElement("div");
  box.className = "modal-box shade-modal";
  box.innerHTML = `<h3>Add annotations</h3>`;

  const rowEntries = [];
  tabState.annotations.forEach((ann) => {
    const row = document.createElement("div");
    row.className = "shade-row";

    const input = document.createElement("input");
    input.type = "text";
    input.style.flex = "1";
    input.maxLength = allowableLength;
    let existing = "";
    for (let c = lo; c <= hi; c++) existing += ann.data[c] || " ";
    input.value = existing.trim() ? existing : "";

    const label = document.createElement("label");
    label.textContent = ann.name;
    label.style.color = input.value.trim() ? "#000" : "#999";

    input.addEventListener("input", () => {
      label.style.color = input.value.trim() ? "#000" : "#999";
    });

    row.append(input, label);
    box.appendChild(row);
    rowEntries.push({ ann, input });
  });

  const commonRow = document.createElement("div");
  commonRow.className = "shade-row";
  const commonInput = document.createElement("input");
  commonInput.type = "text";
  commonInput.readOnly = true;
  commonInput.style.flex = "1";
  commonInput.value = "Common characters: " + ["➰", "⇐", "⇒", "α", "β", "γ", "δ", "ε", "π"].join(", ");
  //commonRow.appendChild(commonInput);
  //box.appendChild(commonRow);

  const radioName = `annotateproc_${Math.random().toString(36).slice(2)}`;
  const procRow = document.createElement("div");
  procRow.className = "shade-row";
  [
    ["Add spaces to beginning", "left"],
    ["Add spaces to end", "right"],
    ["Repeat pattern", "repeat"]
  ].forEach(([text, value]) => {
    const wrap = document.createElement("span");
    const radio = document.createElement("input");
    radio.type = "radio";
    radio.name = radioName;
    radio.value = value;
    if (value === "right") radio.checked = true;
    const label = document.createElement("label");
    label.textContent = " " + text;
    wrap.append(radio, label);
    procRow.appendChild(wrap);
  });
  box.appendChild(procRow);

  function annotate(ann, text, procedure) {
    let result;
    if (procedure === "repeat") {
      result = "";
      if (text.length > 0) {
        while (result.length < allowableLength) result += text;
        result = result.substring(0, allowableLength);
      } else {
        result = " ".repeat(allowableLength);
      }
    } else if (procedure === "left") {
      result = text.padStart(allowableLength, " ");
    } else {
      result = text.padEnd(allowableLength, " ");
    }
    let data = ann.data;
    if (data.length <= hi) data = data.padEnd(hi + 1, " ");
    ann.data = data.substring(0, lo) + result + data.substring(hi + 1);
  }

  const execBtn = document.createElement("button");
  execBtn.textContent = "Annotate";
  execBtn.className = "modal-close-btn";
  execBtn.addEventListener("click", () => {
    runWithLoading(execBtn, () => {
      const checked = procRow.querySelector(`input[name="${radioName}"]:checked`);
      const procedure = checked ? checked.value : "right";
      rowEntries.forEach(({ ann, input }) => annotate(ann, input.value, procedure));
      onApply();
      overlay.remove();
      if (onClose) onClose();
    });
  });
  box.appendChild(execBtn);

  overlay.appendChild(box);
  overlay.addEventListener("click", (e) => {
    if (e.target === overlay) {
      overlay.remove();
      if (onClose) onClose();
    }
  });
  document.body.appendChild(overlay);
}

function showConsensusOptionsModal(tabState, onGenerate) {
  const overlay = document.createElement("div");
  overlay.className = "modal-overlay";
  const box = document.createElement("div");
  box.className = "modal-box shade-modal";
  const radioName = `consensusmode_${Math.random().toString(36).slice(2)}`;
  const isNucleotide = tabState.alphabet === "nucleotide";
  box.innerHTML = `
    <h3>Consensus options</h3>
    <div class="shade-row" style="color:#999;">Consensus types:</div>
    <div class="shade-row" style="flex-direction:column; align-items:flex-start;">
      <div><label><input type="radio" name="${radioName}" value="simple" checked> Simple (default)</label></div>
      <div><label><input type="radio" name="${radioName}" value="dots"> Dots and identity</label></div>
      <div><label style="${isNucleotide ? "color:#666;" : ""}"><input type="radio" name="${radioName}" value="clustal" ${isNucleotide ? "disabled" : ""}> Clustal (* : .)</label></div>
    </div>`;

  const execBtn = document.createElement("button");
  execBtn.textContent = "Generate consensus";
  execBtn.className = "modal-close-btn";
  execBtn.addEventListener("click", () => {
    const checked = box.querySelector(`input[name="${radioName}"]:checked`);
    overlay.remove(); // close the options modal first, the progress overlay replaces it
    // onGenerate is now async (chunked compute + progress); surface failures instead of
    // swallowing them as unhandled rejections
    Promise.resolve(onGenerate(checked ? checked.value : "simple")).catch((err) => {
      console.error("Consensus computation failed:", err);
      alert("Consensus computation failed: " + err.message);
    });
  });
  box.appendChild(execBtn);

  overlay.appendChild(box);
  overlay.addEventListener("click", (e) => {
    if (e.target === overlay) overlay.remove();
  });
  document.body.appendChild(overlay);
}

// Consensus computation ~ allocation-free counting (charCodeAt + typed array
// instead of a Map + toUpperCase per cell). Runs ONCE per column ever, via the
// memoized accessor below; panning recomputes nothing.
function computeConsensusColumn(records, col) {
  const counts = new Int32Array(256); // ASCII char codes; alignments are ASCII in practice
  for (let i = 0; i < records.length; i++) {
    let code = colCodeAt(records[i], col);
    if (code >= 97 && code <= 122) code -= 32; // uppercase a-z (avoid repeated costly toUpperCase)
    if (code < 256) counts[code]++;
  }
  let bestCode = 45,
    bestCount = -1;
  for (let c = 0; c < 256; c++) {
    if (counts[c] > bestCount) {
      bestCount = counts[c];
      bestCode = c;
    }
  }
  return String.fromCharCode(bestCode);
}

// Memoized per-column consensus: computed once per column, cached on the tab,
// invalidated per-column on cell edits and wholesale on import/column deletion.
function consensusCharAt(tabState, col) {
  let cache = tabState.consensusCols;
  if (!cache) cache = tabState.consensusCols = [];
  let ch = cache[col];
  if (ch === undefined) {
    ch = computeConsensusColumn(tabState.records, col);
    // V8's fast-elements backing store dies near 2^27 entries (Chrome-specific;
    // spec allows 2^32-1). Stay far under: beyond this, recompute instead of cache -
    // sweeps never revisit columns, so nothing of value is lost.
    if (col < 1 << 26) cache[col] = ch;
  }
  return ch;
}

function computeConsensus(records, colCount) {
  let result = "";
  for (let c = 0; c < colCount; c++) {
    const counts = new Map();
    for (const rec of records) {
      const ch = (rec.seq[c] || "-").toUpperCase();
      counts.set(ch, (counts.get(ch) || 0) + 1);
    }
    let best = "-",
      bestCount = -1;
    counts.forEach((count, ch) => {
      if (count > bestCount) {
        best = ch;
        bestCount = count;
      }
    });
    result += best;
  }
  return result;
}

async function computeSimpleConsensusJava(tabState, colCount, onProgress) {
  const alphaList = tabState.alphabet === "nucleotide" ? NUCLEOTIDE_ALPHABET : PROTEIN_ALPHABET;
  const charSet = alphaList.map((e) => e.code);
  const seqNum = tabState.records.length;

  // decision-only when the retained load plane covers this width, no re-sweep
  const lp = tabState.loadPlane && tabState.loadPlane.cols >= colCount ? tabState.loadPlane : null;
  const wide = lp ? null : await columnCountsPlane(tabState.records, colCount, onProgress);
  const setCodes = charSet.map((ch) => ch.toUpperCase().charCodeAt(0));
  const result = [];
  for (let c = 0; c < colCount; c++) {
    const counts = {};
    if (lp) {
      const base = c << lp.shift;
      for (let i = 0; i < charSet.length; i++) counts[charSet[i]] = lp.counts[base + lp.toDense[setCodes[i]]];
    } else {
      const base = c << 8;
      for (let i = 0; i < charSet.length; i++) counts[charSet[i]] = wide[base | setCodes[i]];
    }
    // decision logic unchanged
    result.push(
      simpleConsensusDecision(
        charSet.map((ch) => counts[ch]),
        charSet,
        seqNum
      )
    );
  }
  return result;
}

async function computeDotsAndIdentityConsensus(tabState, colCount, onProgress) {
  const records = tabState.records;
  const seqNum = records.length;

  // decision-only when the retained load plane covers this width, no re-sweep
  const lp = tabState.loadPlane && tabState.loadPlane.cols >= colCount ? tabState.loadPlane : null;
  const wide = lp ? null : await columnCountsPlane(records, colCount, onProgress);

  const result = [];
  for (let c = 0; c < colCount; c++) {
    let counts = null;
    if (lp) {
      const base = c << lp.shift;
      if (lp.counts[base + lp.otherSlot] === 0) {
        // dots counts EVERYTHING, gaps included, so unlike clustal, no slot is excluded
        counts = {};
        for (let k = 0; k < lp.otherSlot; k++) {
          const n = lp.counts[base + k];
          if (n > 0) counts[String.fromCharCode(lp.denseChar[k])] = n;
        }
      } // else: an unnamed char is present, it could BE the max or the unanimous
      // identity char, and the bucket can't name it, fall through to exact
    } else {
      counts = {};
      const base = c << 8;
      for (let k = 0; k < 256; k++) {
        const n = wide[base | k];
        if (n > 0) counts[String.fromCharCode(k)] = n;
      }
    }
    if (!counts) {
      // exact per-column fallback, the original per-row scan, verbatim semantics
      counts = {};
      for (let r = 0; r < seqNum; r++) {
        const ch = (records[r].seq[c] || "-").toUpperCase();
        counts[ch] = (counts[ch] || 0) + 1;
      }
    }
    // decision logic unchanged, max-finding and the identity check are order-independent
    let maxFreq = 0;
    let identityChar = null;
    for (const ch of Object.keys(counts)) {
      const freq = counts[ch] / seqNum;
      if (freq > maxFreq) {
        maxFreq = freq;
        if (maxFreq === 1) {
          identityChar = ch;
          break;
        }
      }
    }
    let toUse = " ";
    if (identityChar !== null) toUse = identityChar;
    else if (maxFreq >= 0.25 && maxFreq < 0.5) toUse = ".";
    else if (maxFreq >= 0.5 && maxFreq < 0.75) toUse = ":";
    else if (maxFreq >= 0.75 && maxFreq < 1) toUse = "*";
    result.push(toUse);
  }
  return result;
}

const GLYPH_REF_SIZE = 100;
const GLYPH_CANVAS_SIZE = GLYPH_REF_SIZE * 2.2; // generous margin on all sides
const GLYPH_BASELINE_X = GLYPH_REF_SIZE * 0.6;
const GLYPH_BASELINE_Y = GLYPH_REF_SIZE * 1.6;
const _glyphCache = new Map();

function renderGlyphCanvas(ch, fontFamily, colorHex) {
  const canvas = document.createElement("canvas");
  canvas.width = GLYPH_CANVAS_SIZE;
  canvas.height = GLYPH_CANVAS_SIZE;
  const ctx = canvas.getContext("2d");
  ctx.font = `900 ${GLYPH_REF_SIZE}px ${fontFamily}`;
  ctx.textBaseline = "alphabetic";
  ctx.textAlign = "left";
  ctx.fillStyle = colorHex;
  ctx.fillText(ch, GLYPH_BASELINE_X, GLYPH_BASELINE_Y);
  return canvas;
}

function findInkBoundingBox(canvas) {
  const ctx = canvas.getContext("2d");
  const { width, height } = canvas;
  const data = ctx.getImageData(0, 0, width, height).data;
  let minX = width,
    minY = height,
    maxX = -1,
    maxY = -1;
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      if (data[(y * width + x) * 4 + 3] > 10) {
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
        if (y < minY) minY = y;
        if (y > maxY) maxY = y;
      }
    }
  }
  if (maxX < minX || maxY < minY) return null;
  return { x: minX, y: minY, width: maxX - minX + 1, height: maxY - minY + 1 };
}

function getGlyphBitmap(ch, fontFamily, colorHex) {
  const key = `${ch}|${fontFamily}|${colorHex}`;
  if (_glyphCache.has(key)) return _glyphCache.get(key);
  const canvas = renderGlyphCanvas(ch, fontFamily, colorHex);
  const bbox = findInkBoundingBox(canvas);
  const result = bbox ? { canvas, bbox } : null;
  _glyphCache.set(key, result);
  return result;
}

function drawScaledGlyph(ctx, ch, x, y, targetWidth, targetHeight, colorHex, fontFamily) {
  const glyph = getGlyphBitmap(ch, fontFamily, colorHex);
  if (!glyph) return;
  const { canvas, bbox } = glyph;
  ctx.drawImage(canvas, bbox.x, bbox.y, bbox.width, bbox.height, x, y, targetWidth, targetHeight);
}

function computeColumnLogoInfo(column, alphabetKeys, alphabetSize, useError) {
  const keys = alphabetKeys.filter((k) => k !== "-"); // gaps are neither sampled nor drawn
  let sampleSize = 0;
  column.forEach((ch) => {
    sampleSize++;
  });
  const freq = {};
  keys.forEach((c) => {
    let count = 0;
    for (const ch of column) if (ch === c) count++;
    freq[c] = sampleSize > 0 ? count / sampleSize : 0;
  });
  let uncertainty = 0;
  keys.forEach((c) => {
    const f = freq[c];
    if (f > 0) uncertainty += f * Math.log2(f);
  });
  uncertainty = -uncertainty;
  const errest = useError && sampleSize > 0 ? ((1 / Math.LN2) * (alphabetSize - 1)) / (2 * sampleSize) : 0;
  let infoContent = Math.log2(alphabetSize) - (uncertainty + errest);
  infoContent = Math.max(0, Math.min(infoContent, Math.log2(alphabetSize))); // never above the axis max
  return { freq, infoContent };
}

function drawLogoColumn(ctx, column, colorMap, alphabetKeys, alphabetSize, index, useError, fontFamily, geom) {
  const { freq, infoContent } = computeColumnLogoInfo(column, alphabetKeys, alphabetSize, useError);
  const maxInfo = Math.log2(alphabetSize);
  const actualWorkingHeight = (maxInfo / Math.ceil(maxInfo)) * geom.workingHeight;
  const columnWorkingHeight = maxInfo > 0 ? (infoContent / maxInfo) * actualWorkingHeight : 0;

  const entries = alphabetKeys
    .map((ch) => ({ ch, height: freq[ch] * columnWorkingHeight }))
    .filter((e) => e.height > 0.05)
    .sort((a, b) => a.height - b.height);

  const xval = geom.ORIGIN_X + geom.characterWidth * index;
  let yval = geom.ORIGIN_Y + geom.workingHeight;
  entries.forEach((e) => {
    yval -= e.height;
    drawScaledGlyph(ctx, e.ch, xval, yval, geom.characterWidth, e.height, colorMap[e.ch] || "#000000", fontFamily);
  });
}

function drawLogoAxes(ctx, maxBits, len, geom, fontFamily) {
  ctx.fillStyle = "#000000";
  ctx.fillRect(geom.ORIGIN_X - geom.AXIS_WIDTH, geom.ORIGIN_Y, geom.AXIS_WIDTH, geom.workingHeight + geom.AXIS_WIDTH);
  ctx.fillRect(
    geom.ORIGIN_X - geom.AXIS_WIDTH,
    geom.ORIGIN_Y + geom.workingHeight,
    geom.characterWidth * len + geom.AXIS_WIDTH,
    geom.AXIS_WIDTH
  );

  const xpostickx = geom.ORIGIN_X - 2 * geom.AXIS_WIDTH;
  ctx.font = `bold 12px ${fontFamily}`;
  ctx.textAlign = "right";
  ctx.textBaseline = "middle";
  for (let k = 0; k <= maxBits; k++) {
    const fraction = k / maxBits;
    const yposk = fraction * geom.workingHeight + geom.ORIGIN_Y;
    ctx.fillRect(xpostickx, yposk, geom.AXIS_WIDTH, geom.AXIS_WIDTH);
    ctx.fillText(String(maxBits - k), xpostickx - 4, yposk);
  }

  ctx.save();
  ctx.translate(geom.ORIGIN_X - 26, geom.ORIGIN_Y + geom.workingHeight / 2);
  ctx.rotate(-Math.PI / 2);
  ctx.textAlign = "center";
  ctx.textBaseline = "bottom";
  ctx.fillText("bits", 0, 0);
  ctx.restore();

  ctx.textAlign = "center";
  ctx.textBaseline = "top";
  const yposxlabs = geom.ORIGIN_Y + geom.workingHeight + geom.AXIS_WIDTH + 4;
  for (let k = 1; k <= len; k++) {
    const xposxlab = geom.ORIGIN_X + (k - 1) * geom.characterWidth + geom.characterWidth / 2;
    ctx.fillText(String(k), xposxlab, yposxlabs);
  }
}

// Freeze watchdog (legacy - the user knows when it's freezing, but optimized SlimShadey basically never freezes)
// Detects main-thread stalls ("the page froze") by measuring gaps between timer
// ticks, and on Chromium also watches JS heap usage. The warning shows when the
// page recovers, with a cooldown so it can't spam.
const FREEZE_CHECK_MS = 1000; // tick interval
const FREEZE_STALL_MS = 3000; // extra elapsed time beyond one tick that counts as a freeze
const FREEZE_COOLDOWN_MS = 30000; // minimum time between warnings
const HEAP_WARN_FRACTION = 0.9; // warn when JS heap exceeds 90% of the tab limit (Chromium only)
let freezeLastBeat = performance.now();
let freezeLastWarnAt = 0;

function showFreezeWarningModal() {
  if (document.getElementById("freeze-warning-overlay")) return; // already showing
  const overlay = document.createElement("div");
  overlay.className = "modal-overlay";
  overlay.id = "freeze-warning-overlay";
  const box = document.createElement("div");
  box.className = "modal-box shade-modal";
  box.innerHTML = `<h3>Performance warning</h3>`;

  const msgRow = document.createElement("div");
  msgRow.className = "shade-row";
  msgRow.textContent =
    "You are quickly approaching the memory limits of this browser tab. Consider modifying your workflow.";
  box.appendChild(msgRow);

  const btnRow = document.createElement("div");
  btnRow.className = "shade-row";
  const okBtn = document.createElement("button");
  okBtn.textContent = "OK";
  okBtn.className = "modal-close-btn";
  okBtn.addEventListener("click", () => overlay.remove());
  btnRow.appendChild(okBtn);
  box.appendChild(btnRow);

  overlay.appendChild(box);
  overlay.addEventListener("click", (e) => {
    if (e.target === overlay) overlay.remove();
  });
  document.body.appendChild(overlay);
}

function freezeWatchdogTick() {
  const now = performance.now();
  const gap = now - freezeLastBeat;
  freezeLastBeat = now;
  if (document.hidden) return; // background-tab timer throttling isn't a freeze

  let triggered = gap > FREEZE_CHECK_MS + FREEZE_STALL_MS;
  if (!triggered && performance.memory) {
    const m = performance.memory;
    if (m.jsHeapSizeLimit > 0 && m.usedJSHeapSize / m.jsHeapSizeLimit > HEAP_WARN_FRACTION) triggered = true;
  }
  if (triggered && now - freezeLastWarnAt > FREEZE_COOLDOWN_MS) {
    freezeLastWarnAt = now;
    showFreezeWarningModal();
  }
}

// uncomment below if your implementation needs a freezing watchdog
//setInterval(freezeWatchdogTick, FREEZE_CHECK_MS);

// streamed-download service worker: powers .crswap-free exports
if ("serviceWorker" in navigator) {
  navigator.serviceWorker.register("sw.js").catch(() => {}); // preview iframes may refuse; exports fall back
}

// On-demand render scheduler
// Renderers never self-loop. They register a redraw via requestRender();
// one shared rAF tick drains everything that went dirty this frame.
const _dirtyRenderers = new Set();
let _renderTickArmed = false;

function requestRender(renderFn) {
  _dirtyRenderers.add(renderFn);
  if (_renderTickArmed) return;
  _renderTickArmed = true;
  requestAnimationFrame(() => {
    _renderTickArmed = false;
    _dirtyRenderers.forEach((fn) => fn());
    _dirtyRenderers.clear();
  });
}

//  Simple fixed-row track renderer (annotation / numbering / consensus)
function initTrackRenderer(canvas, wrapperEl, config) {
  const dpr = window.devicePixelRatio || 1;
  let { w: CELL_W, h: CELL_H } = config.getCellDims();

  function sizeCanvas() {
    const rowCount = config.getRowCount();
    canvas.width = wrapperEl.clientWidth * dpr;
    canvas.height = rowCount * CELL_H * dpr;
    canvas.style.width = wrapperEl.clientWidth + "px";
    canvas.style.height = rowCount * CELL_H + "px";
  }
  sizeCanvas();

  const gl = canvas.getContext("webgl2");
  if (!gl) {
    if (!webglAlertShown) {
      webglAlertShown = true;
      alert("WebGL2 not supported");
    }
    return {
      onScroll() {},
      onResize() {},
      rebuildBuffer() {},
      onRowCountChanged() {},
      applyColorOverrides() {},
      setCellSize() {},
      setLuminance() {},
      setHoverCol() {},
      setSelection() {},
      suspend() {},
      resume() {}
    };
  }

  let instData = null;
  let instanceCount = 0;
  let currentScrollX = 0;
  let hoveredKey = -1;
  let prog, vao, atlasTex, instBuf, uni;
  let glSuspended = false;
  const loseExt = gl.getExtension("WEBGL_lose_context");

  // full GL object (re)creation, runs on init and after every context restore
  function setupGL() {
    const compiled = compileMsaProgram(gl);
    prog = compiled.prog;
    vao = compiled.vao;
    atlasTex = compiled.atlasTex;
    instBuf = compiled.instBuf;
    uni = compiled.uni;
    gl.useProgram(prog);
    gl.uniform2f(uni.cellSize, CELL_W * dpr, CELL_H * dpr);
    gl.uniform2f(uni.scroll, 0, 0); // window-relative; rebuildWindow() sets the real value
    gl.uniform2f(uni.res, canvas.width, canvas.height);
    gl.uniform1f(uni.luminance, config.getLuminance());
  }
  setupGL();

  canvas.addEventListener("webglcontextlost", (e) => {
    e.preventDefault(); // required, or the context can never be restored
    glSuspended = true;
  });
  canvas.addEventListener("webglcontextrestored", () => {
    hoveredKey = -1;
    setupGL();
    //rebuild(); // re-uploads instance data and schedules a redraw
    rebuildWindow();
    glSuspended = false;
  });

  // horizontal window: only the visible columns (plus margin) live in the buffer
  let winColStart = 0,
    winCols = 0;

  function viewCols() {
    return Math.ceil(canvas.width / (CELL_W * dpr)) + 1;
  }

  function setScrollUniform() {
    gl.useProgram(prog);
    gl.uniform2f(uni.scroll, currentScrollX - winColStart * CELL_W * dpr, 0);
  }

  let hoverColAbs = -1,
    hoverCellColAbs = -1,
    selLoAbs = -1,
    selHiAbs = -1;

  function setHighlightUniforms() {
    gl.useProgram(prog);
    gl.uniform1f(uni.hoverCol, hoverColAbs < 0 ? -1 : hoverColAbs - winColStart);
    gl.uniform1f(uni.hoverCellCol, hoverCellColAbs < 0 ? -1 : hoverCellColAbs - winColStart);
    gl.uniform1f(uni.selStart, selLoAbs < 0 ? -1 : selLoAbs - winColStart);
    gl.uniform1f(uni.selEnd, selHiAbs < 0 ? -1 : selHiAbs - winColStart);
  }

  function rebuildWindow() {
    const rowCount = config.getRowCount();
    const colCount = config.getColCount();
    const view = viewCols();
    const firstCol = Math.max(0, Math.floor(currentScrollX / (CELL_W * dpr)));
    const cs = Math.max(0, firstCol - view);
    const ce = Math.min(colCount, firstCol + 2 * view);
    winColStart = cs;
    winCols = Math.max(0, ce - cs);
    instanceCount = rowCount * winCols;
    instData = new Float32Array(instanceCount * 6);
    let idx = 0;
    for (let r = 0; r < rowCount; r++) {
      for (let c = cs; c < ce; c++) {
        const { ch, color } = config.cellForFn(r, c);
        instData.set([c - cs, r, color[0], color[1], color[2], glyphIndexFor(ch)], idx * 6);
        idx++;
      }
    }
    gl.bindBuffer(gl.ARRAY_BUFFER, instBuf);
    gl.bufferData(gl.ARRAY_BUFFER, instData, gl.DYNAMIC_DRAW);
    gl.useProgram(prog);
    gl.uniform2f(uni.windowOrigin, winColStart, 0);
    setScrollUniform();
    setHighlightUniforms();
    markDirty();
  }

  function windowNeedsRebuild() {
    const colCount = config.getColCount();
    const view = viewCols();
    const firstCol = Math.max(0, Math.floor(currentScrollX / (CELL_W * dpr)));
    const lastCol = Math.min(colCount, firstCol + view);
    const half = view / 2;
    if (winColStart > 0 && firstCol < winColStart + half) return true;
    if (winColStart + winCols < colCount && lastCol > winColStart + winCols - half) return true;
    return false;
  }
  rebuildWindow();

  function pick(clientX, clientY) {
    const rect = canvas.getBoundingClientRect();
    const x = (clientX - rect.left) * dpr + currentScrollX;
    const y = (clientY - rect.top) * dpr;
    const colCount = config.getColCount();
    const col = Math.floor(x / (CELL_W * dpr));
    const row = Math.floor(y / (CELL_H * dpr));
    if (row < 0 || row >= config.getRowCount() || col < 0 || col >= colCount) return null;
    return { row, col, idx: row * colCount + col };
  }

  if (config.editable) {
    canvas.addEventListener("click", (e) => {
      if (window._activeContextMenu) {
        closeContextMenu();
        return;
      }
      const cell = pick(e.clientX, e.clientY);
      if (!cell) return;
      config.onEdit(cell.row, cell.col, e.clientX, e.clientY);
    });
  }

  canvas.addEventListener("mousemove", (e) => {
    const cell = pick(e.clientX, e.clientY);
    const newKey = cell ? cell.idx : -1;
    if (newKey !== hoveredKey) {
      hoveredKey = newKey;
      gl.useProgram(prog);
      hoverCellColAbs = cell ? cell.col : -1;
      gl.uniform1f(uni.hoverCellCol, hoverCellColAbs < 0 ? -1 : hoverCellColAbs - winColStart);
      gl.uniform1f(uni.hoverCellRow, cell ? cell.row : -1);
      markDirty();
    }
    if (cell && config.onHover) config.onHover(cell.row, cell.col);
    else if (!cell && config.onHoverEnd) config.onHoverEnd();
  });
  canvas.addEventListener("mouseleave", () => {
    if (hoveredKey >= 0) {
      hoveredKey = -1;
      gl.useProgram(prog);
      gl.uniform1f(uni.hoverCellCol, -1);
      gl.uniform1f(uni.hoverCellRow, -1);
      hoverCellColAbs = -1;
      markDirty();
    }
    if (config.onHoverEnd) config.onHoverEnd();
  });

  function render() {
    if (glSuspended) return;
    gl.viewport(0, 0, canvas.width, canvas.height);
    gl.clearColor(0.07, 0.07, 0.07, 1);
    gl.clear(gl.COLOR_BUFFER_BIT);
    gl.useProgram(prog);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, atlasTex);
    gl.bindVertexArray(vao);
    gl.drawArraysInstanced(gl.TRIANGLES, 0, 6, instanceCount);
  }
  function markDirty() {
    requestRender(render);
  }
  markDirty();

  return {
    onScroll(scrollLeft) {
      currentScrollX = scrollLeft * dpr; // keep existing assignment lines as-is
      if (windowNeedsRebuild())
        rebuildWindow(); // sets the scroll uniform and marks dirty
      else {
        setScrollUniform();
        markDirty();
      }
    },
    onResize() {
      sizeCanvas();
      gl.useProgram(prog);
      gl.uniform2f(uni.res, canvas.width, canvas.height);
      // viewport outgrew the buffered window (same gate onScroll uses)
      if (windowNeedsRebuild()) rebuildWindow();
      else {
        setScrollUniform();
        markDirty();
      }
    },
    rebuildBuffer() {
      rebuildWindow();
    },
    onRowCountChanged() {
      sizeCanvas();
      rebuildWindow();
      gl.useProgram(prog);
      gl.uniform2f(uni.res, canvas.width, canvas.height);
    },
    applyColorOverrides(hitList) {
      hitList.forEach(({ row, col, ch, color }) => {
        if (col < winColStart || col >= winColStart + winCols) return; // off-window: model already updated; next rebuild picks it up
        const idx = row * winCols + (col - winColStart);
        if (ch !== undefined) instData[idx * 6 + 5] = glyphIndexFor(ch);
        instData[idx * 6 + 2] = color[0];
        instData[idx * 6 + 3] = color[1];
        instData[idx * 6 + 4] = color[2];
      });
      gl.bindBuffer(gl.ARRAY_BUFFER, instBuf);
      gl.bufferData(gl.ARRAY_BUFFER, instData, gl.DYNAMIC_DRAW);
      markDirty();
    },
    setCellSize(newW, newH) {
      CELL_W = newW;
      CELL_H = newH;
      gl.useProgram(prog);
      gl.uniform2f(uni.cellSize, CELL_W * dpr, CELL_H * dpr);
      sizeCanvas();
      gl.uniform2f(uni.res, canvas.width, canvas.height);
      // cell data is unchanged by a resize/zoom, only rebuild if the
      // viewport outgrew the buffered window (same gate onScroll uses)
      if (windowNeedsRebuild()) rebuildWindow();
      else {
        setScrollUniform();
        markDirty();
      }
    },
    setLuminance(val) {
      gl.useProgram(prog);
      gl.uniform1f(uni.luminance, val);
      markDirty();
    },
    setHoverCol(col) {
      hoverColAbs = col;
      gl.useProgram(prog);
      gl.uniform1f(uni.hoverCol, col < 0 ? -1 : col - winColStart);
      markDirty();
    },
    setSelection(startCol, endCol) {
      selLoAbs = startCol;
      selHiAbs = endCol;
      gl.useProgram(prog);
      gl.uniform1f(uni.selStart, startCol - winColStart);
      gl.uniform1f(uni.selEnd, endCol - winColStart);
      markDirty();
    },
    suspend() {
      if (glSuspended || !loseExt) return;
      glSuspended = true;
      loseExt.loseContext();
    },
    resume() {
      if (!glSuspended || !loseExt) return;
      loseExt.restoreContext(); // the contextrestored handler rebuilds GL state
    }
  };
}

// Alignment (main scrollable) renderer
function initAlignmentRenderer(canvas, alignPanel, spacer, config) {
  const dpr = window.devicePixelRatio || 1;
  let { w: CELL_W, h: CELL_H } = config.getCellDims();
  let rows = config.getRecords().length;
  let cols = config.getColCount();

  function sizeCanvasAndSpacer() {
    spacer.style.width = cols * CELL_W + "px";
    // Do NOT assign spacer.style.height here. createTab owns vertical virtual
    // scrolling and applies a capped physical height through updateVScrollSpacers().
    canvas.width = alignPanel.clientWidth * dpr;
    canvas.height = alignPanel.clientHeight * dpr;
    canvas.style.width = alignPanel.clientWidth + "px";
    canvas.style.height = alignPanel.clientHeight + "px";
  }
  sizeCanvasAndSpacer();

  const gl = canvas.getContext("webgl2");
  if (!gl) {
    if (!webglAlertShown) {
      webglAlertShown = true;
      alert("WebGL2 not supported");
    }
    return {
      onScroll() {},
      onResize() {},
      rebuildBuffer() {},
      applyColorOverrides() {},
      setCellSize() {},
      setLuminance() {},
      setHoverCol() {},
      setHoverRow() {},
      clearSelection() {},
      isSelecting: () => false,
      suspend() {},
      resume() {}
    };
  }

  let prog, vao, atlasTex, instBuf, uni;
  let glSuspended = false;
  const loseExt = gl.getExtension("WEBGL_lose_context");

  function setupGL() {
    const compiled = compileMsaProgram(gl);
    prog = compiled.prog;
    vao = compiled.vao;
    atlasTex = compiled.atlasTex;
    instBuf = compiled.instBuf;
    uni = compiled.uni;
    gl.useProgram(prog);
    gl.uniform2f(uni.cellSize, CELL_W * dpr, CELL_H * dpr);
    gl.uniform2f(uni.scroll, 0, 0); // window-relative; rebuildWindow() sets the real value
    gl.uniform2f(uni.res, canvas.width, canvas.height);
    gl.uniform1f(uni.luminance, config.getLuminance());
  }

  canvas.addEventListener("webglcontextlost", (e) => {
    e.preventDefault();
    glSuspended = true;
  });
  canvas.addEventListener("webglcontextrestored", () => {
    hoveredKey = -1;
    setupGL();
    buildInstanceData(); // rebuilds the windowed buffer from the model
    if (selStartCol >= 0) updateSelectionUniform();
    glSuspended = false;
  });

  let instData, instanceCount;
  let currentScrollX = 0,
    currentScrollY = 0;
  let hoveredKey = -1; // row * cols + col, change detection only
  // Instance window: absolute cell range currently in the buffer.
  let winRowStart = 0,
    winColStart = 0,
    winRows = 0,
    winCols = 0;

  function cellForFn(r, c) {
    const rec = config.getRecords()[r];
    const codes = rec.seqCodes;
    const ch = codes ? (c < codes.length ? charOfCode(codes[c]) : "-") : rec.seq[c] || "-";
    const override = recordColorAt(rec, c);
    const color = override ? hexToRgbFloat(override) : config.getColor(r, c, ch);
    return { ch, color };
  }

  function buildInstanceData() {
    const records = config.getRecords();
    rows = records.length;
    cols = config.getColCount();

    // unique and frequency rely on cached column statistics that may have changed while their modals were closed
    if (config.getShadeMode() === "unique" && config.recomputeUniqueColors) {
      //config.recomputeUniqueColors(cols);
    }
    if (config.getShadeMode() === "frequency" && config.recomputeFrequencyColumns) {
      //config.recomputeFrequencyColumns(cols);
    }
    if (config.getShadeMode() === "matrix" && config.recomputeMatrixColors) {
      config.recomputeMatrixColors(cols);
    }
    if (config.getShadeMode() === "clustalx" && config.recomputeClustalXColors) {
      config.recomputeClustalXColors(cols);
    }
    if (config.getShadeMode() === "sequence" && config.recomputeSequenceColors) {
      config.recomputeSequenceColors();
    }
    rebuildWindow();
  }

  function viewCells() {
    return {
      rows: Math.ceil(canvas.height / (CELL_H * dpr)) + 1,
      cols: Math.ceil(canvas.width / (CELL_W * dpr)) + 1
    };
  }

  function setScrollUniform() {
    gl.useProgram(prog);
    gl.uniform2f(uni.scroll, currentScrollX - winColStart * CELL_W * dpr, currentScrollY - winRowStart * CELL_H * dpr);
  }

  let hoverColAbs = -1,
    hoverCellColAbs = -1,
    selLoAbs = -1,
    selHiAbs = -1;

  // column highlight uniforms are window-relative; emitte again on every window rebuild
  function setHighlightUniforms() {
    gl.useProgram(prog);
    gl.uniform1f(uni.hoverCol, hoverColAbs < 0 ? -1 : hoverColAbs - winColStart);
    gl.uniform1f(uni.hoverCellCol, hoverCellColAbs < 0 ? -1 : hoverCellColAbs - winColStart);
    gl.uniform1f(uni.selStart, selLoAbs < 0 ? -1 : selLoAbs - winColStart);
    gl.uniform1f(uni.selEnd, selHiAbs < 0 ? -1 : selHiAbs - winColStart);
  }

  function rebuildWindow() {
    const view = viewCells();
    // window = viewport + one viewport of margin on each side
    const firstRow = Math.min(Math.max(0, rows - 1), Math.max(0, Math.floor(currentScrollY / (CELL_H * dpr))));
    const firstCol = Math.min(Math.max(0, cols - 1), Math.max(0, Math.floor(currentScrollX / (CELL_W * dpr))));
    const rs = Math.max(0, firstRow - view.rows);
    const re = Math.min(rows, firstRow + 2 * view.rows);
    const cs = Math.max(0, firstCol - view.cols);
    const ce = Math.min(cols, firstCol + 2 * view.cols);
    winRowStart = rs;
    winColStart = cs;
    winRows = Math.max(0, re - rs);
    winCols = Math.max(0, ce - cs);

    instanceCount = winRows * winCols;
    instData = new Float32Array(instanceCount * 6);
    let idx = 0;
    for (let r = rs; r < re; r++) {
      for (let c = cs; c < ce; c++) {
        const { ch, color } = cellForFn(r, c);
        instData.set([c - cs, r - rs, color[0], color[1], color[2], glyphIndexFor(ch)], idx * 6);
        idx++;
      }
    }
    gl.bindBuffer(gl.ARRAY_BUFFER, instBuf);
    gl.bufferData(gl.ARRAY_BUFFER, instData, gl.DYNAMIC_DRAW);
    gl.useProgram(prog);
    gl.uniform2f(uni.windowOrigin, winColStart, winRowStart);
    setScrollUniform();
    setHighlightUniforms();
    markDirty();
  }

  function windowNeedsRebuild() {
    const view = viewCells();
    const firstRow = Math.max(0, Math.floor(currentScrollY / (CELL_H * dpr)));
    const firstCol = Math.max(0, Math.floor(currentScrollX / (CELL_W * dpr)));
    const lastRow = Math.min(rows, firstRow + view.rows);
    const lastCol = Math.min(cols, firstCol + view.cols);
    const halfR = view.rows / 2,
      halfC = view.cols / 2;
    // rebuild when the viewport leaves the window's middle band,
    // unless the window is already pinned to that data edge
    if (winRowStart > 0 && firstRow < winRowStart + halfR) return true;
    if (winRowStart + winRows < rows && lastRow > winRowStart + winRows - halfR) return true;
    if (winColStart > 0 && firstCol < winColStart + halfC) return true;
    if (winColStart + winCols < cols && lastCol > winColStart + winCols - halfC) return true;
    return false;
  }
  setupGL();
  buildInstanceData();

  function pickCell(clientX, clientY) {
    const rect = canvas.getBoundingClientRect();
    const x = (clientX - rect.left) * dpr + currentScrollX;
    const y = (clientY - rect.top) * dpr + currentScrollY;
    const col = Math.floor(x / (CELL_W * dpr));
    const row = Math.floor(y / (CELL_H * dpr));
    if (row < 0 || row >= rows || col < 0 || col >= cols) return null;
    return { row, col };
  }
  function colFromClientX(clientX) {
    const rect = canvas.getBoundingClientRect();
    const x = (clientX - rect.left) * dpr + currentScrollX;
    return Math.floor(x / (CELL_W * dpr));
  }

  function updateSelectionUniform() {
    gl.useProgram(prog);
    const lo = Math.min(selStartCol, selEndCol);
    const hi = Math.max(selStartCol, selEndCol);
    selLoAbs = lo;
    selHiAbs = hi;
    gl.uniform1f(uni.selStart, lo - winColStart);
    gl.uniform1f(uni.selEnd, hi - winColStart);
    markDirty();
    if (config.onSelectionChange) config.onSelectionChange(lo, hi);
  }

  function clearSelection() {
    if (selStartCol < 0 && selLoAbs < 0) return; // nothing to clear
    selStartCol = -1;
    selEndCol = -1;
    selLoAbs = -1;
    selHiAbs = -1;
    gl.useProgram(prog);
    gl.uniform1f(uni.selStart, -1);
    gl.uniform1f(uni.selEnd, -1);
    markDirty();
    if (config.onSelectionChange) config.onSelectionChange(-1, -1);
  }

  let selStartCol = -1,
    selEndCol = -1,
    colSelecting = false;

  let selClearSuppressUntil = 0; // swallow async autoscroll scroll events delivered after mouseup

  const EDGE_ZONE = 30; // px from canvas edge that triggers auto-scroll
  const AUTO_SCROLL_SPEED = 12; // px per tick
  let autoScrollDir = 0; // -1 left, 0 none, 1 right
  let autoScrollInterval = null;

  function startAutoScroll(dir) {
    if (autoScrollDir === dir) return;
    stopAutoScroll();
    autoScrollDir = dir;
    autoScrollInterval = setInterval(() => {
      config.onAutoScrollDelta(dir * AUTO_SCROLL_SPEED);
    }, 16);
  }
  function stopAutoScroll() {
    if (autoScrollInterval) {
      clearInterval(autoScrollInterval);
      autoScrollInterval = null;
    }
    autoScrollDir = 0;
  }

  canvas.addEventListener("mousemove", (e) => {
    const cell = pickCell(e.clientX, e.clientY);
    const newKey = cell ? cell.row * cols + cell.col : -1;
    if (newKey !== hoveredKey) {
      hoveredKey = newKey;
      gl.useProgram(prog);
      hoverCellColAbs = cell ? cell.col : -1;
      gl.uniform1f(uni.hoverCellCol, hoverCellColAbs < 0 ? -1 : hoverCellColAbs - winColStart);
      gl.uniform1f(uni.hoverCellRow, cell ? cell.row : -1);
      markDirty();
      if (cell && config.onHover) config.onHover(cell.row, cell.col);
      else if (!cell && config.onHoverEnd) config.onHoverEnd();
    }
  });
  canvas.addEventListener("mouseleave", () => {
    if (hoveredKey >= 0) {
      hoveredKey = -1;
      gl.useProgram(prog);
      gl.uniform1f(uni.hoverCellCol, -1);
      gl.uniform1f(uni.hoverCellRow, -1);
      hoverCellColAbs = -1;
      markDirty();
    }
    if (config.onHoverEnd) config.onHoverEnd();
  });

  canvas.addEventListener("click", (e) => {
    if (window._activeContextMenu) {
      closeContextMenu();
      return;
    }
    const cellPos = pickCell(e.clientX, e.clientY);
    if (!cellPos) return;
    const record = config.getRecords()[cellPos.row];
    //if (!record.charColors) record.charColors = {};
    let currentChar = record.seq[cellPos.col] || "-"; // let: the virtual patch below updates these
    const overrideHex = recordColorAt(record, cellPos.col);
    let currentColorHex = overrideHex || rgbFloatToHex(config.getColor(cellPos.row, cellPos.col, currentChar));
    showCellEditPopup(
      e.clientX,
      e.clientY,
      currentChar,
      currentColorHex,
      (newChar, newColorHex) => {
        if (record.vsrc) {
          // virtual row: sequence bytes live in the File, color-only edits until
          // the Phase 3 edit overlay. Char writes would crash on the facade.
          setRecordColor(record, cellPos.col, newColorHex);
          applyColorOverrides([
            { row: cellPos.row, col: cellPos.col, ch: currentChar, color: hexToRgbFloat(newColorHex) }
          ]);
          return;
        }
        const codes = record.seqCodes;
        const code = newChar.charCodeAt(0);
        let oldCode = 45; // '-', the pad-extended case
        if (codes && cellPos.col < codes.length && code <= 255) {
          oldCode = codes[cellPos.col]; // capture BEFORE the write
          codes[cellPos.col] = code; // byte row: in-place write
        } else {
          // string path, or widen a byte row back to a string
          if (codes) {
            record.seq = SEQ_FACADE_DECODER.decode(codes);
            delete record.seqCodes;
          }
          let seq = record.seq;
          oldCode = cellPos.col < seq.length ? seq.charCodeAt(cellPos.col) : 45;
          if (seq.length <= cellPos.col) seq = seq.padEnd(cellPos.col + 1, "-");
          record.seq = seq.substring(0, cellPos.col) + newChar + seq.substring(cellPos.col + 1);
        }
        setRecordColor(record, cellPos.col, newColorHex);
        applyColorOverrides([{ row: cellPos.row, col: cellPos.col, ch: newChar, color: hexToRgbFloat(newColorHex) }]);
        config.onDataChanged(cellPos.col, oldCode, code);
      },
      () => {
        clearRecordColor(record, cellPos.col);
        const ch = record.seq[cellPos.col] || "-";
        applyColorOverrides([
          { row: cellPos.row, col: cellPos.col, ch, color: config.getColor(cellPos.row, cellPos.col, ch) }
        ]);
      }
    );
    // virtual tab, row not resident yet: the popup opened on placeholder data -
    // fetch the page and patch the popup in place when the real bytes land
    if (record.vsrc && !record.vsrc.peekRowQuiet(cellPos.row)) {
      const popup = document.querySelector(".cell-edit-popup");
      record.vsrc.ensureRow(cellPos.row).then(() => {
        const realChar = record.seq[cellPos.col] || "-";
        const realHex =
          recordColorAt(record, cellPos.col) || rgbFloatToHex(config.getColor(cellPos.row, cellPos.col, realChar));
        currentChar = realChar; // the Apply closure reads these, keep them honest too
        currentColorHex = realHex;
        const ci = popup && popup.querySelector(".cell-edit-char-input");
        const co = popup && popup.querySelector('input[type="color"]');
        if (ci) ci.value = realChar;
        if (co) co.value = realHex;
      });
    }
  });

  canvas.addEventListener("contextmenu", (e) => e.preventDefault());
  canvas.addEventListener("mousedown", (e) => {
    if (e.button === 0 && selStartCol >= 0) clearSelection();
    if (e.button !== 2) return;
    e.preventDefault();
    closeContextMenu();
    const col = colFromClientX(e.clientX);
    if (col < 0 || col >= cols) return;
    colSelecting = true;
    selStartCol = col;
    selEndCol = col;
    updateSelectionUniform();
  });
  window.addEventListener("mousemove", (e) => {
    if (!colSelecting) return;
    const col = colFromClientX(e.clientX);
    selEndCol = Math.max(0, Math.min(cols - 1, col));
    updateSelectionUniform();

    const rect = canvas.getBoundingClientRect();
    const distFromLeft = e.clientX - rect.left;
    const distFromRight = rect.right - e.clientX;
    if (distFromLeft >= 0 && distFromLeft < EDGE_ZONE) {
      startAutoScroll(-1);
    } else if (distFromRight >= 0 && distFromRight < EDGE_ZONE) {
      startAutoScroll(1);
    } else {
      stopAutoScroll();
    }
  });
  window.addEventListener("mouseup", (e) => {
    if (e.button !== 2 || !colSelecting) return;
    colSelecting = false;
    stopAutoScroll();
    selClearSuppressUntil = performance.now() + 150;
    const lo = Math.min(selStartCol, selEndCol),
      hi = Math.max(selStartCol, selEndCol);
    showColumnContextMenu(
      e.clientX,
      e.clientY,
      lo,
      hi,
      (lo2, hi2) => {
        config.onDeleteColumns(lo2, hi2);
        buildInstanceData();
        sizeCanvasAndSpacer();
      },
      (lo2, hi2, onModalClose) => config.onAnnotateColumns(lo2, hi2, onModalClose),
      (lo2, hi2, onModalClose) => config.onBlockShadeColumns(lo2, hi2, onModalClose),
      (lo2, hi2) => config.onGenerateLogo(lo2, hi2),
      (lo2, hi2) => config.onExportColumns(lo2, hi2),
      (lo2, hi2) => config.onCopyColumns(lo2, hi2),
      clearSelection
    );
  });
  // Touch column selection: long-press then drag
  const LONG_PRESS_MS = 400;
  const MOVE_CANCEL_PX = 10;
  let touchSelTimer = null;
  let touchSelActive = false;
  let suppressNextClick = false;
  let touchStartX = null,
    touchStartY = null,
    touchStartScrollLeft = 0,
    touchStartScrollTop = 0,
    touchStartRealV = 0; // logical scroll at gesture start
  let touchAutoScrollInterval = null;

  function stopTouchAutoScroll() {
    if (touchAutoScrollInterval) {
      clearInterval(touchAutoScrollInterval);
      touchAutoScrollInterval = null;
    }
  }
  function startTouchAutoScroll(dir) {
    stopTouchAutoScroll();
    touchAutoScrollInterval = setInterval(() => {
      config.onAutoScrollDelta(dir * AUTO_SCROLL_SPEED);
      // recompute the column under the (stationary) finger as content scrolls beneath it
      selEndCol = Math.max(0, Math.min(cols - 1, colFromClientX(lastTouchX)));
      updateSelectionUniform();
    }, 16);
  }

  canvas.addEventListener(
    "touchstart",
    (e) => {
      if (e.touches.length !== 1) return;
      const t = e.touches[0];
      touchStartX = t.clientX;
      touchStartY = t.clientY;
      lastTouchX = t.clientX;
      touchSelActive = false;
      touchSelTimer = setTimeout(() => {
        const col = colFromClientX(lastTouchX);
        if (col < 0 || col >= cols) return;
        touchSelActive = true;
        selStartCol = col;
        selEndCol = col;
        updateSelectionUniform();
        if (navigator.vibrate) navigator.vibrate(10);
      }, LONG_PRESS_MS);
    },
    { passive: true }
  );

  canvas.addEventListener(
    "touchmove",
    (e) => {
      const t = e.touches[0];
      if (!t) return;
      lastTouchX = t.clientX;
      if (!touchSelActive) {
        if (Math.abs(t.clientX - touchStartX) > MOVE_CANCEL_PX || Math.abs(t.clientY - touchStartY) > MOVE_CANCEL_PX) {
          clearTimeout(touchSelTimer);
          touchSelTimer = null;
        }
        return; // not selecting so let the scroll handlers work
      }
      e.preventDefault();
      e.stopPropagation(); // keep alignPanel's touch-scroll from fighting the selection
      selEndCol = Math.max(0, Math.min(cols - 1, colFromClientX(t.clientX)));
      updateSelectionUniform();
      const rect = canvas.getBoundingClientRect();
      const distFromLeft = t.clientX - rect.left;
      const distFromRight = rect.right - t.clientX;
      if (distFromLeft >= 0 && distFromLeft < EDGE_ZONE) startTouchAutoScroll(-1);
      else if (distFromRight >= 0 && distFromRight < EDGE_ZONE) startTouchAutoScroll(1);
      else stopTouchAutoScroll();
    },
    { passive: false }
  );

  canvas.addEventListener("touchend", (e) => {
    clearTimeout(touchSelTimer);
    touchSelTimer = null;
    if (!touchSelActive) return;
    touchSelActive = false;
    stopTouchAutoScroll();
    selClearSuppressUntil = performance.now() + 150;
    suppressNextClick = true; // a click fires after touchend, don't let it open the cell editor
    const t = e.changedTouches[0];
    const lo = Math.min(selStartCol, selEndCol);
    const hi = Math.max(selStartCol, selEndCol);
    showColumnContextMenu(
      t.clientX,
      t.clientY,
      lo,
      hi,
      (lo2, hi2) => {
        config.onDeleteColumns(lo2, hi2);
        buildInstanceData();
        sizeCanvasAndSpacer();
      },
      (lo2, hi2, onModalClose) => config.onAnnotateColumns(lo2, hi2, onModalClose),
      (lo2, hi2, onModalClose) => config.onBlockShadeColumns(lo2, hi2, onModalClose),
      (lo2, hi2) => config.onGenerateLogo(lo2, hi2),
      (lo2, hi2) => config.onExportColumns(lo2, hi2),
      (lo2, hi2) => config.onCopyColumns(lo2, hi2),
      clearSelection
    );
  });

  canvas.addEventListener("touchcancel", () => {
    clearTimeout(touchSelTimer);
    touchSelTimer = null;
    touchSelActive = false;
    stopTouchAutoScroll();
  });

  function render() {
    gl.viewport(0, 0, canvas.width, canvas.height);
    gl.clearColor(0.07, 0.07, 0.07, 1);
    gl.clear(gl.COLOR_BUFFER_BIT);
    gl.useProgram(prog);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, atlasTex);
    gl.bindVertexArray(vao);
    gl.drawArraysInstanced(gl.TRIANGLES, 0, 6, instanceCount);
  }
  function markDirty() {
    requestRender(render);
  }
  markDirty();

  function applyColorOverrides(hitList) {
    hitList.forEach(({ row, col, ch, color }) => {
      if (row < winRowStart || row >= winRowStart + winRows || col < winColStart || col >= winColStart + winCols) {
        return; // off-window: the data model is already updated; the next window rebuild picks it up
      }
      const idx = (row - winRowStart) * winCols + (col - winColStart);
      if (ch !== undefined) instData[idx * 6 + 5] = glyphIndexFor(ch);
      instData[idx * 6 + 2] = color[0];
      instData[idx * 6 + 3] = color[1];
      instData[idx * 6 + 4] = color[2];
    });
    gl.bindBuffer(gl.ARRAY_BUFFER, instBuf);
    gl.bufferData(gl.ARRAY_BUFFER, instData, gl.DYNAMIC_DRAW);
    markDirty();
  }
  return {
    onScroll(scrollTop, scrollLeft) {
      currentScrollY = scrollTop * dpr;
      currentScrollX = scrollLeft * dpr;
      if (windowNeedsRebuild())
        rebuildWindow(); // sets the scroll uniform and marks dirty
      else {
        setScrollUniform();
        markDirty();
      }
    },
    onResize() {
      sizeCanvasAndSpacer();
      gl.useProgram(prog);
      gl.uniform2f(uni.res, canvas.width, canvas.height);
      // viewport outgrew the buffered window (same gate onScroll uses)
      if (windowNeedsRebuild()) rebuildWindow();
      else {
        setScrollUniform();
        markDirty();
      } // viewport size changed, so the window must too
    },
    rebuildBuffer() {
      const t0 = performance.now();
      buildInstanceData();
      sizeCanvasAndSpacer();
      console.log("[rebuild]", (performance.now() - t0).toFixed(1) + "ms");
    },
    applyColorOverrides,
    setCellSize(newW, newH) {
      CELL_W = newW;
      CELL_H = newH;
      gl.useProgram(prog);
      gl.uniform2f(uni.cellSize, CELL_W * dpr, CELL_H * dpr);
      sizeCanvasAndSpacer();
      gl.uniform2f(uni.res, canvas.width, canvas.height);
      // cell data is unchanged by a resize/zoom, only rebuild if the
      // viewport outgrew the buffered window (same gate onScroll uses)
      if (windowNeedsRebuild()) rebuildWindow();
      else {
        setScrollUniform();
        markDirty();
      }
    },
    setLuminance(val) {
      gl.useProgram(prog);
      gl.uniform1f(uni.luminance, val);
      markDirty();
    },
    setHoverCol(col) {
      hoverColAbs = col;
      gl.useProgram(prog);
      gl.uniform1f(uni.hoverCol, col < 0 ? -1 : col - winColStart);
      markDirty();
    },
    clearSelection,
    isSelecting: () => colSelecting || touchSelActive || performance.now() < selClearSuppressUntil,
    setHoverRow(row) {
      gl.useProgram(prog);
      gl.uniform1f(uni.hoverRow, row);
      markDirty();
    },
    suspend() {
      if (glSuspended || !loseExt) return;
      glSuspended = true;
      loseExt.loseContext();
    },
    resume() {
      if (!glSuspended || !loseExt) return;
      loseExt.restoreContext(); // the contextrestored handler rebuilds GL state
    }
  };
}

// Per-column sequence logo strip
function initLogoStrip(cfg) {
  const { tabState, stripEl, canvasEl, alignPanel, hScrollTrack, getColCount, getCellDims, realHScroll } = cfg;
  const ctx = canvasEl.getContext("2d");
  const FONT = "Consolas";
  const ROW_SAMPLE = 1000; // cap rows sampled per column, for huge alignments
  const PAD = 24;
  let W = 0,
    H = 0;
  let img = null,
    imgCols = 0,
    imgColStart = 0,
    blitScrollX = null,
    imgCw = 0;
  const colCache = new Map(); // col -> { stack, frac, colorMap }

  function sizeCanvas() {
    const w = stripEl.clientWidth,
      h = stripEl.clientHeight;
    if (w === W && h === H) return;
    W = w;
    H = h;
    if (W && H) {
      canvasEl.width = W;
      canvasEl.height = H;
      img = null;
      draw(true);
    }
  }

  function ensureImage() {
    const cw = Math.max(1, getCellDims().w);
    const viewCols = Math.ceil(W / cw) + 2 * PAD;
    const needPx = viewCols * cw;
    // keep the buffer only if it's wide enough in PIXELS for the current cell
    // width, a buffer allocated at a smaller cw clips when zoomed in
    if (img && img.width >= needPx && img.height === Math.max(1, H)) return;
    imgCols = viewCols + PAD * 2;
    img = document.createElement("canvas");
    img.width = imgCols * cw;
    img.height = Math.max(1, H);
    blitScrollX = null;
  }

  // Virtual tabs: exact per-column frequencies from the retained load plane -
  // never touches paged rows (a sampled scan through facades would kick a fetch
  // per sampled row and storm the pager)
  function computeColFromPlane(col) {
    const lp = tabState.loadPlane;
    const rows = tabState.records.length;
    if (!lp || !rows) return null;
    const alphaList = tabState.alphabet === "nucleotide" ? NUCLEOTIDE_ALPHABET : PROTEIN_ALPHABET;
    const keys = alphaList.map((e) => e.code).filter((k) => k !== "-");
    const base = col << lp.shift;
    const freq = {};
    for (const ch of keys) {
      const n = lp.counts[base + lp.toDense[ch.charCodeAt(0)]];
      freq[ch] = n / rows; // plane folds lowercase; gaps/dots aren't in keys
    }
    let uncertainty = 0;
    for (const ch of keys) {
      const f = freq[ch];
      if (f > 0) uncertainty -= f * Math.log2(f);
    }
    const maxInfo = Math.log2(keys.length);
    const infoContent = Math.max(0, Math.min(maxInfo - uncertainty, maxInfo)); // useError=false ⇒ no errest
    return {
      stack: keys
        .map((ch) => ({ ch, f: freq[ch] || 0 }))
        .filter((e) => e.f > 0.001)
        .sort((a, b) => a.f - b.f),
      frac: maxInfo > 0 ? infoContent / maxInfo : 0,
      colorMap: tabState.colors[tabState.alphabet]
    };
  }

  function computeCol(col) {
    const rows = tabState.records.length;
    if (!rows) return null;
    if (tabState.virtual) return computeColFromPlane(col); // plane-exact, zero page traffic
    const stride = Math.max(1, Math.floor(rows / ROW_SAMPLE));
    const column = [];
    for (let r = 0; r < rows; r += stride) {
      let code = colCodeAt(tabState.records[r], col);
      if (code >= 97 && code <= 122) code -= 32; // uppercase a-z
      column.push(charOfCode(code)); // shared 1-char strings, no allocation
    }
    const alphaList = tabState.alphabet === "nucleotide" ? NUCLEOTIDE_ALPHABET : PROTEIN_ALPHABET;
    const keys = alphaList.map((e) => e.code).filter((k) => k !== "-");
    const { freq, infoContent } = computeColumnLogoInfo(column, keys, keys.length, false);
    const maxInfo = Math.log2(keys.length);
    return {
      stack: keys
        .map((ch) => ({ ch, f: freq[ch] || 0 }))
        .filter((e) => e.f > 0.001)
        .sort((a, b) => a.f - b.f),
      frac: maxInfo > 0 ? infoContent / maxInfo : 0,
      colorMap: tabState.colors[tabState.alphabet]
    };
  }

  function renderRange(c0, c1) {
    const cw = Math.max(1, getCellDims().w);
    const ictx = img.getContext("2d");
    ictx.clearRect(0, 0, img.width, img.height);
    const workH = H - 4;
    for (let c = c0; c < c1; c++) {
      let entry = colCache.get(c);
      if (entry === undefined) {
        entry = computeCol(c);
        colCache.set(c, entry);
      }
      if (!entry) continue;
      const colH = entry.frac * workH;
      if (colH < 1) continue;
      const x = (c - imgColStart) * cw;
      let y = H - 2; // stack grows upward
      for (const e of entry.stack) {
        const h = e.f * colH;
        y -= h;
        if (h >= 1.5) {
          const rgb = entry.colorMap[e.ch] || [1, 1, 1];
          drawScaledGlyph(ictx, e.ch, x + 0.5, y, cw - 1, h, rgbFloatToHex(rgb), FONT);
        }
      }
    }
  }

  function draw(force) {
    if (!W || !H) return;
    const cw = Math.max(1, getCellDims().w);
    const sx = realHScroll();
    const firstCol = Math.max(0, Math.floor(sx / cw) - PAD);
    const lastCol = Math.min(getColCount() - 1, Math.ceil((sx + W) / cw) + PAD);
    if (lastCol < firstCol) {
      ctx.clearRect(0, 0, W, H);
      return;
    }
    ensureImage();
    const need = force || blitScrollX === null || imgColStart !== firstCol || imgCw !== cw;
    if (need) {
      imgColStart = firstCol;
      imgCw = cw; // remember the cell width this buffer was rendered at
      renderRange(firstCol, lastCol + 1);
    }
    const dx = imgColStart * cw - sx;
    if (dx !== blitScrollX || need) {
      ctx.clearRect(0, 0, W, H);
      ctx.drawImage(img, dx, 0);
      blitScrollX = dx;
    }
  }

  const scheduleDraw = () => requestRender(() => draw(false));
  alignPanel.addEventListener("scroll", scheduleDraw, { passive: true });
  hScrollTrack.addEventListener("scroll", scheduleDraw, { passive: true });

  // periodic draw for resize/layout self-heal only, the column cache is never
  // cleared here; edits invalidate explicitly via invalidate()
  const timer = setInterval(() => {
    if (!cfg.isActive()) return;
    sizeCanvas();
    draw(false);
  }, 400);

  sizeCanvas();
  draw(true);
  return {
    destroy: () => clearInterval(timer),
    invalidate(col) {
      if (col === undefined) colCache.clear();
      else colCache.delete(col);
      draw(true);
    },
    reindex(lo, hi) {
      reindexColumnCacheMap(colCache, lo, hi);
      draw(true);
    }
  };
}

// Conservation bars (per visible column)
function initConservationStrip(cfg) {
  const {
    tabState,
    stripEl,
    canvasEl,
    alignPanel,
    hScrollTrack,
    getColCount,
    getCellDims,
    realHScroll,
    consensusCache
  } = cfg;
  const ctx = canvasEl.getContext("2d");
  let W = 0,
    H = 0;
  let img = null,
    imgCols = 0,
    imgColStart = 0,
    blitScrollX = null, // offscreen buffer state
    imgCw = 0;
  const PAD = 24; // extra columns of margin each side
  let tipEl = null,
    lastTipCol = -1;

  function sizeCanvas() {
    const w = stripEl.clientWidth,
      h = stripEl.clientHeight;
    if (w === W && h === H) return;
    W = w;
    H = h;
    if (W && H) {
      canvasEl.width = W;
      canvasEl.height = H;
      img = null;
      draw(true);
    }
  }

  function ensureImage() {
    const cw = Math.max(1, getCellDims().w);
    const viewCols = Math.ceil(W / cw) + 2 * PAD;
    const needPx = viewCols * cw;
    // keep the buffer only if it's wide enough in PIXELS for the current cell
    // width, a buffer allocated at a smaller cw clips when zoomed in
    if (img && img.width >= needPx && img.height === Math.max(1, H)) return;
    imgCols = viewCols + PAD * 2;
    img = document.createElement("canvas");
    img.width = imgCols * cw;
    img.height = Math.max(1, H);
    blitScrollX = null;
  }
  // % identity of most common non-gap char in col; returns {ch, pct} or null
  const statCache = new Map(); // col -> {ch, pct} | null, depends on data only, never on scroll or zoom

  // Virtual tabs: exact majority from the retained load plane, never touches
  // paged rows. Columns where the OTHER bucket (exotic bytes the plane can't
  // name) would win return null, same as all-gap columns: the bar is omitted.
  function colStatsFromPlane(col) {
    const lp = tabState.loadPlane;
    const rows = tabState.records.length;
    if (!lp || !rows) return null;
    const base = col << lp.shift;
    let bestSlot = -1,
      bestCount = 0;
    for (let s = 0; s < lp.otherSlot; s++) {
      const code = lp.denseChar[s];
      if (code === 45 || code === 46) continue; // gaps don't count, same as the sampled path
      const n = lp.counts[base + s];
      if (n > bestCount) {
        bestCount = n;
        bestSlot = s;
      }
    }
    if (bestSlot < 0) return null;
    if (lp.counts[base + lp.otherSlot] > bestCount) return null;
    return { ch: String.fromCharCode(lp.denseChar[bestSlot]), pct: (100 * bestCount) / rows };
  }

  // identity of most common non-gap char in col, returns {ch, pct} or null.
  // Row-sampled (same cap as the logo strip) and allocation-free: at 20k rows a
  // full scan was 20k string allocations per column; now <=1000 sampled reads.
  const ROW_SAMPLE = 1000;
  function colStats(col) {
    if (statCache.has(col)) return statCache.get(col);
    const rows = tabState.records.length;
    let result = null;
    if (rows && tabState.virtual) {
      result = colStatsFromPlane(col); // plane-exact, zero page traffic
    } else if (rows) {
      const stride = Math.max(1, Math.floor(rows / ROW_SAMPLE));
      const counts = new Int32Array(256); // ASCII char codes
      let sampled = 0;
      let bestCode = -1,
        bestCount = 0;
      for (let r = 0; r < rows; r += stride) {
        sampled++;
        let code = colCodeAt(tabState.records[r], col); // raw byte-row read
        if (code >= 97 && code <= 122) code -= 32; // uppercase a-z
        if (code === 45 || code === 46 || code >= 256) continue; // gaps don't count
        counts[code]++;
        if (counts[code] > bestCount) {
          bestCount = counts[code];
          bestCode = code;
        }
      }
      if (bestCode >= 0) result = { ch: String.fromCharCode(bestCode), pct: (100 * bestCount) / sampled };
    }
    statCache.set(col, result);
    return result;
  }

  function renderRange(c0, c1) {
    const cw = getCellDims().w;
    const ictx = img.getContext("2d");
    ictx.clearRect(0, 0, img.width, img.height);
    ictx.fillStyle = "#9aa3ad";
    for (let c = c0; c < c1; c++) {
      const s = colStats(c);
      if (!s) continue;
      const x = (c - imgColStart) * cw;
      const h = Math.max(2, (s.pct / 100) * (H - 4));
      ictx.fillRect(x + 1, H - 2 - h, cw - 2, h);
    }
  }

  function draw(force) {
    if (!W || !H) return;
    const cw = Math.max(1, getCellDims().w);
    const sx = realHScroll();
    const firstCol = Math.max(0, Math.floor(sx / cw) - PAD);
    const lastCol = Math.min(getColCount() - 1, Math.ceil((sx + W) / cw) + PAD);
    if (lastCol < firstCol) {
      ctx.clearRect(0, 0, W, H);
      return;
    }
    ensureImage();
    const need = force || blitScrollX === null || imgColStart !== firstCol || imgCw !== cw;
    if (need) {
      imgColStart = firstCol;
      imgCw = cw; // remember the cell width this buffer was rendered at
      renderRange(firstCol, lastCol + 1);
    }
    const dx = imgColStart * cw - sx;
    if (dx !== blitScrollX || need) {
      ctx.clearRect(0, 0, W, H);
      ctx.drawImage(img, dx, 0);
      blitScrollX = dx;
    }
  }

  const scheduleDraw = () => requestRender(() => draw(false));
  alignPanel.addEventListener("scroll", scheduleDraw, { passive: true });
  hScrollTrack.addEventListener("scroll", scheduleDraw, { passive: true });

  // mouseover readout
  function ensureTip() {
    if (!tipEl) {
      tipEl = document.createElement("div");
      tipEl.className = "conservation-tip";
      document.body.appendChild(tipEl);
    }
  }
  canvasEl.addEventListener("mousemove", (e) => {
    const b = canvasEl.getBoundingClientRect();
    const cw = Math.max(1, getCellDims().w);
    const col = Math.floor((e.clientX - b.left + realHScroll()) / cw);
    if (col !== lastTipCol) {
      lastTipCol = col;
      ensureTip();
      const s = colStats(col);
      tipEl.textContent = s ? `Col ${col + 1}: ${s.ch} · ${s.pct.toFixed(1)}%` : `Col ${col + 1}: -`;
      tipEl.style.display = "block";
    }
    tipEl.style.left = e.clientX - 12 + "px";
    tipEl.style.top = e.clientY - 12 + "px";
  });
  canvasEl.addEventListener("mouseleave", () => {
    lastTipCol = -1;
    if (tipEl) tipEl.style.display = "none";
  });

  // keep bars fresh when records/consensus change: re-render current window
  // every 5th tick, drop cached column stats so edits self-heal
  // (same cadence as the logo strip's colCache clear)
  let tick = 0;
  // periodic draw for resize/layout self-heal only, the stat cache is NEVER
  // cleared here; edits invalidate explicitly via invalidate()
  const timer = setInterval(() => {
    if (!cfg.isActive()) return;
    sizeCanvas();
    draw(false);
  }, 400);
  sizeCanvas();
  draw(true);
  return {
    destroy: () => {
      clearInterval(timer);
      if (tipEl) tipEl.remove();
    },
    invalidate(col) {
      if (col === undefined) statCache.clear();
      else statCache.delete(col);
      draw(true);
    },
    // lazy column-shift: surviving stats stay valid at shifted indexes
    reindex(lo, hi) {
      reindexColumnCacheMap(statCache, lo, hi);
      draw(true);
    }
  };
}

// Bottom overview strip (birds-eye + viewport connectors)
function initOverviewStrip(cfg) {
  const {
    tabState,
    stripEl,
    canvasEl,
    markerEl,
    polygon,
    contentColumnEl,
    alignPanel,
    hScrollTrack,
    getColCount,
    getCellDims,
    realHScroll
  } = cfg;
  const ctx2d = canvasEl.getContext("2d");
  let W = 0,
    H = 0,
    tick = 0,
    dragging = false;

  function sizeCanvas() {
    const w = stripEl.clientWidth,
      h = stripEl.clientHeight;
    if (w === W && h === H) return;
    W = w;
    H = h;
    if (W && H) {
      canvasEl.width = W;
      canvasEl.height = H;
      renderImage();
    }
  }

  function renderImage() {
    const cols = getColCount(),
      rows = tabState.records.length;
    if (!W || !H) return;
    if (!rows) {
      ctx2d.clearRect(0, 0, W, H);
      return;
    }
    const img = ctx2d.createImageData(W, H);
    const d = img.data;
    for (let py = 0; py < H; py++) {
      const r = Math.min(rows - 1, Math.floor((py * rows) / H));
      const rec = tabState.records[r];
      let codes = rec.seqCodes; // byte rows: raw reads, no facade trap per pixel
      if (!codes && tabState.virtual) {
        codes = tabState.virtual.peekRowQuiet(r); // cache-only, a strip never kicks fetches
        if (!codes) continue; // non-resident row: transparent pixels until its page lands
      }
      for (let px = 0; px < W; px++) {
        const c = Math.min(cols - 1, Math.floor((px * cols) / W));
        const override = recordColorAt(rec, c);
        const ch = codes ? (c < codes.length ? charOfCode(codes[c]) : "-") : rec.seq[c] || "-";
        const rgb = override ? hexToRgbFloat(override) : getShadeColor(tabState, r, c, ch);
        const i = (py * W + px) * 4;
        d[i] = Math.round(rgb[0] * 255);
        d[i + 1] = Math.round(rgb[1] * 255);
        d[i + 2] = Math.round(rgb[2] * 255);
        d[i + 3] = 255;
      }
    }
    ctx2d.putImageData(img, 0, 0);
  }

  function trackFromReal(realX) {
    if (cfg.getHScrollScale() === 1) return realX;
    const maxSpacer = hScrollTrack.scrollWidth - hScrollTrack.clientWidth;
    const maxReal = Math.max(0, getColCount() * getCellDims().w - alignPanel.clientWidth);
    if (maxSpacer <= 0 || maxReal <= 0) return 0;
    return (realX / maxReal) * maxSpacer;
  }

  function updateOverlay() {
    if (!cfg.isActive() || !W || !H) return;
    const cols = getColCount(),
      rows = tabState.records.length;
    const { w: cw, h: ch } = getCellDims();
    const totalW = Math.max(1, cols * cw);
    const totalH = Math.max(1, rows * ch);
    const rw = Math.min(W, Math.max(6, (alignPanel.clientWidth / totalW) * W));
    const rh = Math.min(H, Math.max(6, (alignPanel.clientHeight / totalH) * H));
    const mx = Math.min(W - rw, Math.max(0, (realHScroll() / totalW) * W));
    const my = Math.min(H - rh, Math.max(0, (cfg.realVScroll() / totalH) * H));
    markerEl.style.left = mx + "px";
    markerEl.style.top = my + "px";
    markerEl.style.width = rw + "px";
    markerEl.style.height = rh + "px";
    // trapezoid: alignment viewport bottom corners -> marker top corners
    const panelL = alignPanel.offsetLeft;
    const panelR = panelL + alignPanel.clientWidth;
    const panelB = cfg.consensusContentEl.offsetTop + cfg.consensusContentEl.clientHeight;
    const mL = stripEl.offsetLeft + mx,
      mR = mL + rw;
    const mT = stripEl.offsetTop + my;
    cfg.connectorsSvg.setAttribute("viewBox", `0 0 ${contentColumnEl.clientWidth} ${contentColumnEl.clientHeight}`);
    polygon.setAttribute("points", `${panelL},${panelB} ${panelR},${panelB} ${mR},${mT} ${mL},${mT}`);
  }

  const scheduleOverlay = () => requestRender(updateOverlay);
  alignPanel.addEventListener("scroll", scheduleOverlay, { passive: true });
  hScrollTrack.addEventListener("scroll", scheduleOverlay, { passive: true });

  function jumpTo(clientX, clientY) {
    const b = canvasEl.getBoundingClientRect();
    const fx = Math.min(1, Math.max(0, (clientX - b.left) / b.width));
    const fy = Math.min(1, Math.max(0, (clientY - b.top) / b.height));
    const { w: cw, h: ch } = getCellDims();
    const maxRealX = Math.max(0, getColCount() * cw - alignPanel.clientWidth);
    const maxY = Math.max(0, tabState.records.length * ch - alignPanel.clientHeight);
    hScrollTrack.scrollLeft = trackFromReal(
      Math.min(maxRealX, Math.max(0, fx * getColCount() * cw - alignPanel.clientWidth / 2))
    );
    cfg.setRealVScroll(Math.min(maxY, Math.max(0, fy * tabState.records.length * ch - alignPanel.clientHeight / 2)));
    scheduleOverlay();
  }

  stripEl.addEventListener("pointerdown", (e) => {
    e.preventDefault();
    dragging = true;
    stripEl.setPointerCapture(e.pointerId);
    jumpTo(e.clientX, e.clientY);
  });
  stripEl.addEventListener("pointermove", (e) => {
    if (dragging) jumpTo(e.clientX, e.clientY);
  });
  stripEl.addEventListener("pointerup", () => {
    dragging = false;
  });
  stripEl.addEventListener("pointercancel", () => {
    dragging = false;
  });

  let imgDirty = true;
  const timer = setInterval(() => {
    if (!cfg.isActive()) return;
    sizeCanvas(); // also catches resizes and late layout
    scheduleOverlay();
    // re-sample when something changed, else once every ~4s as a backstop
    // (was every ~1s: a full W×H shade-lookup storm landing mid-pan)
    if (imgDirty || tick++ % 16 === 0) {
      imgDirty = false;
      renderImage();
    }
  }, 250);

  sizeCanvas();
  scheduleOverlay();
  return {
    destroy: () => clearInterval(timer),
    invalidate() {
      imgDirty = true;
    }
  };
}

//  Viewport (bird's-eye overview)
function showViewportModal(tabState, vp) {
  const rows0 = tabState.records.length;
  if (rows0 === 0) return;

  const overlay = document.createElement("div");
  overlay.className = "modal-overlay";
  const box = document.createElement("div");
  box.className = "modal-box shade-modal";
  box.innerHTML = `<h3>Viewport</h3>`;

  const hintRow = document.createElement("div");
  hintRow.className = "shade-row";
  hintRow.style.color = "#999";
  hintRow.textContent = "Click or drag the overview to move the visible area.";
  box.appendChild(hintRow);

  // miniature sized to the alignment's aspect ratio
  const OW = 320;
  const OH = Math.max(40, Math.min(200, Math.round((OW * rows0) / Math.max(1, vp.getColCount()))));
  const wrap = document.createElement("div");
  wrap.style.position = "relative";
  wrap.style.width = `${OW}px`;
  wrap.style.height = `${OH}px`;
  wrap.style.border = "1px solid #444";
  wrap.style.cursor = "crosshair";
  wrap.style.touchAction = "none";

  const canvas = document.createElement("canvas");
  canvas.width = OW;
  canvas.height = OH;
  canvas.style.display = "block";
  wrap.appendChild(canvas);

  const rect = document.createElement("div");
  rect.style.position = "absolute";
  rect.style.border = "2px solid #ff3333";
  rect.style.background = "rgba(255, 51, 51, 0.12)";
  rect.style.boxSizing = "border-box";
  rect.style.pointerEvents = "none";
  wrap.appendChild(rect);
  box.appendChild(wrap);

  const ctx2d = canvas.getContext("2d");

  function renderImage() {
    const cols = vp.getColCount();
    const rows = tabState.records.length;
    const img = ctx2d.createImageData(OW, OH);
    const d = img.data;
    for (let py = 0; py < OH; py++) {
      const r = Math.min(rows - 1, Math.floor((py * rows) / OH));
      const rec = tabState.records[r];
      let codes = rec.seqCodes; // byte rows: raw reads, no facade trap per pixel
      if (!codes && tabState.virtual) {
        codes = tabState.virtual.peekRowQuiet(r); // cache-only, a strip never kicks fetches
        if (!codes) continue; // non-resident row: transparent pixels until its page lands
      }
      for (let px = 0; px < OW; px++) {
        const c = Math.min(cols - 1, Math.floor((px * cols) / OW));
        const override = recordColorAt(rec, c);
        const ch = codes ? (c < codes.length ? charOfCode(codes[c]) : "-") : rec.seq[c] || "-";
        const rgb = override ? hexToRgbFloat(override) : getShadeColor(tabState, r, c, ch);
        const i = (py * OW + px) * 4;
        d[i] = Math.round(rgb[0] * 255);
        d[i + 1] = Math.round(rgb[1] * 255);
        d[i + 2] = Math.round(rgb[2] * 255);
        d[i + 3] = 255;
      }
    }
    ctx2d.putImageData(img, 0, 0);
  }

  function trackFromReal(realX) {
    if (vp.getHScrollScale() === 1) return realX;
    const maxSpacer = vp.hScrollTrack.scrollWidth - vp.hScrollTrack.clientWidth;
    const maxReal = Math.max(0, vp.getColCount() * vp.getCellDims().w - vp.alignPanel.clientWidth);
    if (maxSpacer <= 0 || maxReal <= 0) return 0;
    return (realX / maxReal) * maxSpacer; // exact inverse of realHScroll()
  }

  function updateRect() {
    const cols = vp.getColCount();
    const rows = tabState.records.length;
    const { w: cw, h: ch } = vp.getCellDims();
    const totalW = Math.max(1, cols * cw);
    const totalH = Math.max(1, rows * ch);
    const x = (vp.realHScroll() / totalW) * OW;
    const y = (vp.realVScroll() / totalH) * OH;
    const rw = Math.min(OW, Math.max(6, (vp.alignPanel.clientWidth / totalW) * OW));
    const rh = Math.min(OH, Math.max(6, (vp.alignPanel.clientHeight / totalH) * OH));
    rect.style.left = `${Math.min(OW - rw, Math.max(0, x))}px`;
    rect.style.top = `${Math.min(OH - rh, Math.max(0, y))}px`;
    rect.style.width = `${rw}px`;
    rect.style.height = `${rh}px`;
  }

  let dragging = false;
  function jumpTo(clientX, clientY) {
    const b = canvas.getBoundingClientRect();
    const fx = Math.min(1, Math.max(0, (clientX - b.left) / b.width));
    const fy = Math.min(1, Math.max(0, (clientY - b.top) / b.height));
    const { w: cw, h: ch } = vp.getCellDims();
    const cols = vp.getColCount();
    const rows = tabState.records.length;
    const maxRealX = Math.max(0, cols * cw - vp.alignPanel.clientWidth);
    const maxY = Math.max(0, rows * ch - vp.alignPanel.clientHeight);
    const targetX = Math.min(maxRealX, Math.max(0, fx * cols * cw - vp.alignPanel.clientWidth / 2));
    const targetY = Math.min(maxY, Math.max(0, fy * rows * ch - vp.alignPanel.clientHeight / 2));
    vp.hScrollTrack.scrollLeft = trackFromReal(targetX); // its scroll listener syncs everything
    vp.setRealVScroll(targetY);
    updateRect();
  }

  function onMove(e) {
    if (dragging) jumpTo(e.clientX, e.clientY);
  }
  function onUp() {
    dragging = false;
  }
  wrap.addEventListener("pointerdown", (e) => {
    e.preventDefault();
    dragging = true;
    jumpTo(e.clientX, e.clientY);
  });
  window.addEventListener("pointermove", onMove);
  window.addEventListener("pointerup", onUp);

  // live: rectangle follows scrolling; miniature re-samples once a second
  let tick = 0;
  const timer = setInterval(() => {
    updateRect();
    if (tick++ % 4 === 0) renderImage();
  }, 250);

  const btnRow = document.createElement("div");
  btnRow.className = "shade-row";
  const closeBtn = document.createElement("button");
  closeBtn.textContent = "Close";
  closeBtn.className = "modal-close-btn";
  closeBtn.addEventListener("click", close);
  btnRow.appendChild(closeBtn);
  box.appendChild(btnRow);

  function close() {
    clearInterval(timer);
    window.removeEventListener("pointermove", onMove);
    window.removeEventListener("pointerup", onUp);
    overlay.remove();
  }

  overlay.appendChild(box);
  overlay.addEventListener("click", (e) => {
    if (e.target === overlay) close();
  });
  document.body.appendChild(overlay);

  renderImage();
  updateRect();
}

// Tab management
let tabCount = 0;
const tabRenderers = new Map(); // tabId -> [annotationCtl, numberingCtl, alignmentCtl, consensusCtl]

function createTab(name, records, presetState = null) {
  tabCount++;
  const tabId = `tab-${tabCount}`;

  // every window-level listener this tab registers carries this signal,
  // so closeTab can remove them all at once with ac.abort()
  const ac = new AbortController();
  const { signal } = ac;

  const tabState = {
    records,
    annotations: (presetState && presetState.annotations) || [
      { name: "(Annotations_1)", data: "", colors: {} },
      { name: "(Annotations_2)", data: "", colors: {} },
      { name: "(Annotations_3)", data: "", colors: {} },
      { name: "(Annotations_4)", data: "", colors: {} }
    ],
    consensusOverrides: (presetState && presetState.consensusOverrides) || {},
    consensusColors: (presetState && presetState.consensusColors) || {},
    shadeMode: "standard",
    shadeConfig: {
      matrix: {
        mode: "sequence",
        refSeqId: records[0] ? records[0].id : null,
        shadeMaster: true,
        frequency: 0.5,
        matchHex: "#000000",
        mismatchHex: "#FFFFFF",
        matrixName: "BLOSUM62"
      },
      unique: { maxCount: 1, shadeGaps: true, colorHex: "#000000" },
      sequence: {
        refSeqId: records[0] ? records[0].id : null,
        masterColorHex: "#000000",
        identityHex: "#000000",
        similarHex: "#B6B6B6",
        diffHex: "#FFFFFF"
      },
      regex: {
        enabled: false,
        patterns: [{ pattern: "", colorHex: "FF0000" }],
        hitsByRow: null,
        baseMode: null,
        appliedHits: []
      },
      scanprosite: { enabled: false, hitsByRow: null, colorsByName: {}, baseMode: null, appliedHits: [] },
      frequency: {
        threshold: 0.5,
        identityHex: "#000000",
        similarHex: "#B6B6B6",
        diffHex: "#FFFFFF",
        inverse: false
      }
    },
    alphabet: (presetState && presetState.alphabet) || detectAlphabet(records),
    colors: buildDefaultColors(),
    fontSize: (presetState && presetState.fontSize) || 14,
    luminance: presetState && presetState.luminance !== undefined ? presetState.luminance : 0.179,
    firstIndex: (presetState && presetState.firstIndex) || 1,
    collapse: (presetState && presetState.collapse) || false,
    liveHover: presetState && presetState.liveHover !== undefined ? presetState.liveHover : true,
    refreshDelay: presetState ? presetState.refreshDelay : 0,
    shadeCleared: !!(presetState && presetState.shadeCleared), // .blim loads: colors are baked, base shading renders white
    consensusBaked: (presetState && presetState.consensusBaked) || null, // baked consensus planes from .blim
    loadPlane: presetState && presetState.loadPlane ? presetState.loadPlane : null, // dense counts plane from the load sweep
    colorPack: presetState && presetState.colorPack ? presetState.colorPack : null,
    virtual: presetState && presetState.virtual ? presetState.virtual : null, // virtual-row pager, rows live in the File, paged on demand
    uniqueColCounts: [],
    matrixCache: null,
    clustalXColors: null
  };
  console.log("[createTab] state ready,", tabState.records.length, "rows");

  const invalidateMotifCaches = () => {
    for (const key of ["regex", "scanprosite"]) {
      const cfg = tabState.shadeConfig[key];
      if (!cfg) continue;
      cfg.hitsByRow = null; // cached hit positions, wrong after any structural edit
      cfg.appliedHits = []; // revert list, reverting at stale coordinates corrupts colors
    }
  };

  tabState.records.forEach((rec) => {
    if (rec.charColors && !rec.colorIdx) {
      rec.colorIdx = colorIdxFromObject(rec.charColors, rec.seq.length);
      delete rec.charColors;
    }
  });

  // chromosome-scale: move rows off the V8 string heap into byte arrays (cage escape).
  // Gated by total cells so everyday alignments keep plain strings. The .blim loader
  // already emits byte rows; this covers FASTA and .slim imports.
  {
    let totalCells = 0;
    for (const rec of tabState.records) totalCells += rec.seqCodes ? rec.seqCodes.length : rec.seq.length; // seqCodes first - rec.seq would fire the lazy getter on 6M rows
    if (totalCells > 50e6) {
      for (const rec of tabState.records) {
        if (rec.seqCodes || typeof rec.seq !== "string") continue; // byte rows (and lazy-facade rows) need no conversion - and typeof rec.seq would fire the getter
        const codes = encodeRowToBytes(rec.seq);
        if (codes) {
          rec.seqCodes = codes;
          //rec.seq = makeSeqFacade(codes); // the old string becomes collectable here
          attachLazyFacade(rec); // the old string becomes collectable here
        }
      }
      console.log("[createTab] byte rows settled");
    }
  }

  function setShadeMode(mode) {
    tabState.shadeCleared = false;
    tabState.records.forEach((rec) => {
      rec.colorIdx = null;
      rec.colorPacked = null; // baked layer wiped too, shade covers all, per the layering contract
      rec.colorSparse = null;
    });
    tabState.shadeMode = mode;
    scheduleRebuild();
    consensusCtl.rebuildBuffer();
  }

  function getColCount() {
    let n = 1;
    const recs = tabState.records;
    for (let i = 0; i < recs.length; i++) {
      const rec = recs[i];
      const l = rec.seqCodes ? rec.seqCodes.length : rec.seq.length; // raw read, no facade trap
      if (l > n) n = l;
    }
    const anns = tabState.annotations;
    for (let i = 0; i < anns.length; i++) if (anns[i].data.length > n) n = anns[i].data.length;
    return n;
  }

  function getCellDims() {
    return cellDimsFor(tabState.fontSize);
  }
  function getLuminance() {
    return tabState.luminance;
  }

  // Tab button
  const btn = document.createElement("div");
  btn.className = "tab-btn";
  btn.dataset.tabId = tabId;
  const nameSpan = document.createElement("span");
  nameSpan.className = "tab-name";
  nameSpan.textContent = name;
  nameSpan.title = "Double-click to rename";
  nameSpan.addEventListener("dblclick", (e) => {
    e.stopPropagation();
    nameSpan.contentEditable = "true";
    nameSpan.focus();
    document.execCommand("selectAll", false, null);
  });
  nameSpan.addEventListener("blur", () => {
    nameSpan.contentEditable = "false";
    if (!nameSpan.textContent.trim()) nameSpan.textContent = "Untitled";
  });
  nameSpan.addEventListener("keydown", (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      nameSpan.blur();
    }
  });
  const closeBtn = document.createElement("span");
  closeBtn.className = "tab-close";
  closeBtn.textContent = "\u00d7";
  btn.appendChild(nameSpan);
  btn.appendChild(closeBtn);
  btn.addEventListener("click", () => activateTab(tabId, btn));
  document.getElementById("tabBar").appendChild(btn);

  // Panel DOM
  const panel = document.createElement("div");
  panel.className = "tab-panel";
  panel.id = tabId;
  panel.innerHTML = `
    <div class="tab-settings-bar">
      <div class="setting-group file-menu-group"><button class="fileMenuBtn">File \u25BE</button></div>
      <div class="setting-group shade-menu-group"><button class="shadeMenuBtn">Shade \u25BE</button></div>
      <div class="setting-group">
        <label>Font size</label>
        <input type="range" class="fontSizeInput" min="6" max="40" value="14" step="1">
        <span class="fontSizeLabel">14px</span>
      </div>
      <div class="setting-group">
        <label>Luminance</label>
        <input type="range" class="luminanceInput" min="0" max="1" value="0.179" step="0.001">
        <span class="luminanceLabel">0.179</span>
      </div>
      <div class="setting-group">
        <label>Alphabet</label>
        <div class="alphabet-toggle">
          <button class="alphaBtn" data-val="nucleotide">Nucleotide</button>
          <button class="alphaBtn" data-val="protein">Protein</button>
        </div>
      </div>
      <div class="setting-group hover-info-group"><span class="hoverInfo"></span></div>
    </div>
    <div class="msa-container">
      <div class="names-column">
        <div class="track-names annotation-names"></div>
        <div class="track-names numbering-names"><div class="track-row-label">Position</div></div>
        <div class="names-panel"></div>
        <div class="track-names consensus-names"><div class="track-row-label">Consensus</div></div>
      </div>
      <div class="divider"></div>
      <div class="content-column">
        <div class="track-content annotation-content"><canvas></canvas></div>
        <div class="track-content numbering-content"><canvas></canvas></div>
        <div class="alignment-panel">
          <div class="canvas-sticky-wrapper"><canvas class="msa-canvas"></canvas></div>
          <div class="scroll-spacer"></div>
        </div>
        <div class="track-content consensus-content"><canvas></canvas></div>
        <div class="h-scrollbar-track"><div class="h-scrollbar-spacer"></div></div><div class="logo-strip"><canvas class="logo-canvas"></canvas></div><div class="conservation-strip"><canvas class="conservation-canvas"></canvas></div><div class="overview-strip"><canvas class="overview-canvas"></canvas><div class="overview-marker"></div></div><svg class="overview-connectors"><polygon class="overview-polygon" points=""/></svg></div></div>
      </div>
    </div>`;
  document.getElementById("tabPanels").appendChild(panel);
  activateTab(tabId, btn);

  console.log("[createTab] DOM mounted");

  // DOM refs
  const msaContainerEl = panel.querySelector(".msa-container");
  const namesColumn = panel.querySelector(".names-column");
  const annotationNamesEl = panel.querySelector(".annotation-names");
  const namesPanel = panel.querySelector(".names-panel");
  const dividerEl = panel.querySelector(".divider");
  const annotationContentEl = panel.querySelector(".annotation-content");
  const annotationCanvas = annotationContentEl.querySelector("canvas");
  const numberingContentEl = panel.querySelector(".numbering-content");
  const numberingCanvas = numberingContentEl.querySelector("canvas");
  const alignPanel = panel.querySelector(".alignment-panel");
  const alignCanvas = panel.querySelector(".msa-canvas");
  const spacer = panel.querySelector(".scroll-spacer");
  const consensusContentEl = panel.querySelector(".consensus-content");
  const consensusCanvas = consensusContentEl.querySelector("canvas");
  const hScrollTrack = panel.querySelector(".h-scrollbar-track");
  const hScrollSpacer = panel.querySelector(".h-scrollbar-spacer");
  const hoverInfoEl = panel.querySelector(".hoverInfo");
  const contentColumnEl = panel.querySelector(".content-column");
  const overviewStripEl = panel.querySelector(".overview-strip");
  const overviewCanvas = overviewStripEl.querySelector(".overview-canvas");
  const overviewMarker = overviewStripEl.querySelector(".overview-marker");
  const overviewSvg = panel.querySelector(".overview-connectors");
  const overviewPolygon = overviewSvg.querySelector(".overview-polygon");
  const conservationStripEl = panel.querySelector(".conservation-strip");
  const conservationCanvas = conservationStripEl.querySelector(".conservation-canvas");
  const logoStripEl = panel.querySelector(".logo-strip");
  const logoCanvas = logoStripEl.querySelector(".logo-canvas");

  function applyCssVars() {
    const { h } = getCellDims();
    panel.style.setProperty("--tab-font-size", `${tabState.fontSize}px`);
    panel.style.setProperty("--tab-cell-h", `${h}px`);
  }
  applyCssVars();

  function applyFixedHeights() {
    const { h } = getCellDims();
    annotationNamesEl.style.height = `${tabState.annotations.length * h}px`;
    annotationContentEl.style.height = `${tabState.annotations.length * h}px`;
    numberingContentEl.style.height = `${h}px`;
    consensusContentEl.style.height = `${h}px`;
  }
  applyFixedHeights();

  let hScrollScale = 1; // <1 when content would exceed the browser's element-width cap

  // Vertical counterpart to hScrollScale. Firefox becomes unreliable around
  // ~8.95M CSS px of scrollable height; keep the physical DOM span safely below
  // that, while all renderer math continues to use real alignment pixels.
  const MAX_V_SCROLL_SPAN = 8000000;
  let vScrollScale = 1;

  function realAlignmentHeight() {
    return Math.max(0, tabState.records.length * getCellDims().h);
  }

  // Rebuild both vertical spacers to the same capped physical height. The
  // alignment and names panels must have identical physical scroll geometry so
  // raw scrollTop can be copied between them without drifting.
  function updateVScrollSpacers() {
    const realHeight = realAlignmentHeight();
    vScrollScale = realHeight > MAX_V_SCROLL_SPAN ? MAX_V_SCROLL_SPAN / realHeight : 1;
    const physicalHeight = Math.max(1, realHeight * vScrollScale) + "px";

    spacer.style.height = physicalHeight;
    namesPanel._vScrollScale = vScrollScale; //<- this line! without it, renderNameWindow's
    //   (namesPanel._vScrollScale || 1) regenerates the
    //   full-height spacer on every render

    if (namesPanel.vstate && namesPanel.vstate.spacer) {
      namesPanel.vstate.spacer.style.height = physicalHeight;
    }
  }

  // Physical DOM scrollTop -> logical alignment pixel offset. This is what the
  // WebGL renderer, row picker, and names virtualizer must use.
  function realVScroll() {
    if (vScrollScale === 1) return alignPanel.scrollTop;

    const physicalMax = alignPanel.scrollHeight - alignPanel.clientHeight;
    const realMax = Math.max(0, realAlignmentHeight() - alignPanel.clientHeight);
    return physicalMax > 0 ? (alignPanel.scrollTop * realMax) / physicalMax : 0;
  }

  // Logical alignment pixel offset -> physical DOM scrollTop. Use this for any
  // programmatic vertical navigation; never assign logical pixels directly to
  // `.scrollTop` once vScrollScale is below 1.
  function setRealVScroll(realY) {
    const realMax = Math.max(0, realAlignmentHeight() - alignPanel.clientHeight);
    const clamped = Math.max(0, Math.min(realMax, realY));

    if (vScrollScale === 1) {
      alignPanel.scrollTop = clamped;
      return;
    }

    const physicalMax = alignPanel.scrollHeight - alignPanel.clientHeight;
    alignPanel.scrollTop = realMax > 0 ? (clamped * physicalMax) / realMax : 0;
  }

  function updateHScrollSpacer() {
    const { w } = getCellDims();
    const realWidth = getColCount() * w;
    const MAX_SPAN = 30000000; // stay under the 2^25px (~33.5M) element-width limit
    hScrollScale = realWidth > MAX_SPAN ? MAX_SPAN / realWidth : 1;
    hScrollSpacer.style.width = `${realWidth * hScrollScale}px`;
    updateVScrollSpacers();
  }
  // map the (possibly compressed) scrollbar position back to real content pixels
  function realHScroll() {
    if (hScrollScale === 1) return hScrollTrack.scrollLeft;
    const maxSpacerScroll = hScrollTrack.scrollWidth - hScrollTrack.clientWidth;
    if (maxSpacerScroll <= 0) return 0;
    const maxRealScroll = Math.max(0, getColCount() * getCellDims().w - alignPanel.clientWidth);
    return hScrollTrack.scrollLeft * (maxRealScroll / maxSpacerScroll);
  }

  // exact inverse of realHScroll(): put the scroller at a real-content pixel position
  function setRealHScroll(realX) {
    if (hScrollScale === 1) {
      hScrollTrack.scrollLeft = Math.max(0, realX);
      return;
    }
    const maxSpacer = hScrollTrack.scrollWidth - hScrollTrack.clientWidth;
    const maxReal = Math.max(0, getColCount() * getCellDims().w - alignPanel.clientWidth);
    hScrollTrack.scrollLeft = maxReal > 0 && maxSpacer > 0 ? (Math.max(0, realX) / maxReal) * maxSpacer : 0;
  }

  function scrollToCol(col) {
    const { w } = getCellDims();
    const cols = getColCount();
    const target = Math.max(0, Math.min(cols - 1, col));
    const realX = target * w - alignPanel.clientWidth / 2; // center the column
    // exact inverse of realHScroll()
    if (hScrollScale === 1) {
      hScrollTrack.scrollLeft = Math.max(0, realX);
    } else {
      const maxSpacer = hScrollTrack.scrollWidth - hScrollTrack.clientWidth;
      const maxReal = Math.max(0, cols * w - alignPanel.clientWidth);
      hScrollTrack.scrollLeft = maxReal > 0 && maxSpacer > 0 ? (Math.max(0, realX) / maxReal) * maxSpacer : 0;
    }
    // setting scrollLeft fires the track's scroll listener, which syncs all four tracks
  }

  function showGotoColumnModal() {
    const overlay = document.createElement("div");
    overlay.className = "modal-overlay";
    const box = document.createElement("div");
    box.className = "modal-box shade-modal";
    box.innerHTML = `<h3>Go to column</h3>`;

    const row = document.createElement("div");
    row.className = "shade-row";
    const input = document.createElement("input");
    input.type = "text";
    input.inputMode = "numeric";
    input.style.width = "90px";
    const label = document.createElement("label");
    label.textContent = `Column (1\u2013${getColCount()})`;
    row.append(input, label);
    box.appendChild(row);

    const go = () => {
      const n = parseInt(input.value, 10);
      if (!Number.isNaN(n)) {
        scrollToCol(n - 1); // UI is 1-based, internals are 0-based! the one time i miss programming in R
        overlay.remove();
      }
    };
    input.addEventListener("keydown", (e) => {
      e.stopPropagation(); // keep the panel's key handlers out of this
      if (e.key === "Enter") {
        e.preventDefault();
        go();
      }
    });

    const btnRow = document.createElement("div");
    btnRow.className = "shade-row";
    const goBtn = document.createElement("button");
    goBtn.textContent = "Go";
    goBtn.className = "modal-close-btn";
    goBtn.addEventListener("click", go);
    const cancelBtn = document.createElement("button");
    cancelBtn.textContent = "Cancel";
    cancelBtn.className = "modal-close-btn";
    cancelBtn.addEventListener("click", () => overlay.remove());
    btnRow.append(goBtn, cancelBtn);
    box.appendChild(btnRow);

    overlay.appendChild(box);
    overlay.addEventListener("click", (e) => {
      if (e.target === overlay) overlay.remove();
    });
    document.body.appendChild(overlay);
    input.focus();
  }

  function updateAlignmentHeight() {
    const { h } = getCellDims();
    const rowCount = tabState.records.length;
    const naturalHeight = Math.max(rowCount, 1) * h;
    const otherTracksHeight =
      annotationContentEl.offsetHeight +
      numberingContentEl.offsetHeight +
      consensusContentEl.offsetHeight +
      hScrollTrack.offsetHeight +
      logoStripEl.offsetHeight +
      conservationStripEl.offsetHeight +
      overviewStripEl.offsetHeight;
    const availableHeight = Math.max(h * 4, msaContainerEl.clientHeight - otherTracksHeight);
    const finalHeight = Math.min(naturalHeight, availableHeight);
    alignPanel.style.height = `${finalHeight}px`;
    namesPanel.style.height = `${finalHeight}px`;
    if (namesPanel._vstate) renderNameWindow(namesPanel, tabState, refreshAfterRecordsChanged);
    if (typeof alignmentCtl !== "undefined") alignmentCtl.onResize();
  }

  // consensus is computed per column on demand, windowed rendering means only
  // visible columns are ever computed, so tab loading is O(1) in columns.
  // The Proxy keeps every existing `consensusStr[c]` / `.length` read working.
  const consensusCache = new Map();
  const consensusStr = new Proxy(
    {},
    {
      get: (t, prop) => {
        if (typeof prop === "symbol") return undefined;
        if (prop === "length") return getColCount();
        const c = Number(prop);
        if (!Number.isInteger(c)) return undefined;
        const baked = tabState.consensusBaked;
        if (baked && baked.chars[c]) return String.fromCharCode(baked.chars[c]);
        let ch = consensusCache.get(c);
        // temporary, in the Proxy get trap, around the consensusCharAt call:
        if (ch === undefined) {
          try {
            ch = consensusCharAt(tabState, c);
          } catch (e) {
            console.error("consensusCharAt failed at column", c, JSON.stringify(tabState.records.map((r) => r.seq[c])));
            throw e;
          }
          if (consensusCache.size < 1 << 22) consensusCache.set(c, ch);
        }
        return ch;
      }
    }
  );

  function refreshConsensus() {
    consensusCache.clear(); // outer memo (the Proxy's Map)
    tabState.consensusCols = null; // inner memo (consensusCharAt's array), without this, stale chars survive
  }

  // the .blim loader stores consensusBaked.colors as null when the plane is entirely
  // default (saves ~2 bytes/column at chromosome scale), null reads as 0 everywhere
  const bakedColorAt = (c) =>
    tabState.consensusBaked && tabState.consensusBaked.colors ? tabState.consensusBaked.colors[c] : 0;

  function exportColumnsAsNewTab(lo, hi) {
    const newRecords = tabState.records.map((rec, r) => {
      const codes = rec.seqCodes; // hoisted - per-cell rec.seq reads would fire the lazy facade on every row
      const newSeq = [];
      const newCharColors = {};
      for (let c = lo; c <= hi; c++) {
        const ch = codes ? (c < codes.length ? charOfCode(codes[c]) : "-") : rec.seq[c] || "-";
        newSeq.push(ch);
        const override = recordColorAt(rec, c);
        const bgHex = override || rgbFloatToHex(getShadeColor(tabState, r, c, ch));
        newCharColors[c - lo] = bgHex;
      }
      return {
        id: rec.id,
        header: rec.header,
        seq: newSeq.join(""),
        charColors: newCharColors
      };
    });

    const newAnnotations = tabState.annotations.map((ann) => {
      let newData = "";
      const newColors = {};
      for (let c = lo; c <= hi; c++) {
        const ch = ann.data[c] || " ";
        newData += ch;
        const override = ann.colors && ann.colors[c];
        newColors[c - lo] = override || rgbFloatToHex(ANNOTATION_BG);
      }
      return { name: ann.name, data: newData, colors: newColors };
    });

    const newConsensusOverrides = {};
    const newConsensusColors = {};
    for (let c = lo; c <= hi; c++) {
      const overrideChar = tabState.consensusOverrides[c];
      const ch = overrideChar !== undefined ? overrideChar : consensusStr[c] || "-";
      const overrideHex = tabState.consensusColors[c];
      const bgHex = overrideHex || "#FFFFFF";
      newConsensusOverrides[c - lo] = ch;
      newConsensusColors[c - lo] = bgHex;
    }

    createTab(`${getTabDisplayName()} (cols ${lo + 1}-${hi + 1})`, newRecords, {
      annotations: newAnnotations,
      consensusOverrides: newConsensusOverrides,
      consensusColors: newConsensusColors,
      alphabet: tabState.alphabet,
      fontSize: tabState.fontSize,
      luminance: tabState.luminance,
      firstIndex: tabState.firstIndex + lo,
      collapse: tabState.collapse,
      liveHover: tabState.liveHover,
      refreshDelay: tabState.refreshDelay
    });
  }

  // Track renderers
  const annotationCtl = initTrackRenderer(annotationCanvas, annotationContentEl, {
    getRowCount: () => tabState.annotations.length,
    getColCount,
    getCellDims,
    getLuminance,
    editable: true,
    cellForFn: (r, c) => {
      const entry = tabState.annotations[r];
      const ch = (entry && entry.data[c]) || " ";
      const override = entry && entry.colors && entry.colors[c];
      return { ch, color: override ? hexToRgbFloat(override) : ANNOTATION_BG };
    },
    onEdit: (r, c, clientX, clientY) => {
      const entry = tabState.annotations[r];
      if (!entry) return;
      if (!entry.colors) entry.colors = {};
      const current = entry.data[c] || " ";
      const overrideHex = entry.colors[c];
      const currentColorHex = overrideHex || rgbFloatToHex(ANNOTATION_BG);
      showCellEditPopup(
        clientX,
        clientY,
        current,
        currentColorHex,
        (newChar, newColorHex) => {
          let row = entry.data;
          if (row.length <= c) row = row.padEnd(c + 1, " ");
          entry.data = row.substring(0, c) + newChar + row.substring(c + 1);
          entry.colors[c] = newColorHex;
          annotationCtl.rebuildBuffer();
        },
        () => {
          delete entry.colors[c];
          annotationCtl.rebuildBuffer();
        }
      );
    },
    onHover: (r, c) => handleHover("annotation", r, c),
    onHoverEnd: () => handleHoverEnd()
  });

  const numberingCtl = initTrackRenderer(numberingCanvas, numberingContentEl, {
    getRowCount: () => 1,
    getColCount,
    getCellDims,
    getLuminance,
    editable: false,
    cellForFn: (r, c) => {
      const pos = c + 1;
      let ch = " ";
      if (pos % 10 === 0) ch = String(Math.floor(pos / 10) % 10);
      else if (pos % 5 === 0) ch = ".";
      return { ch, color: NUMBERING_BG };
    },
    onHover: (r, c) => handleHover("numbering", r, c),
    onHoverEnd: () => handleHoverEnd()
  });

  const consensusCtl = initTrackRenderer(consensusCanvas, consensusContentEl, {
    getRowCount: () => 1,
    getColCount,
    getCellDims,
    getLuminance,
    editable: true,
    cellForFn: (r, c) => {
      const overrideChar = tabState.consensusOverrides[c];
      const ch = overrideChar !== undefined ? overrideChar : consensusStr[c] || "-";
      const overrideHex = tabState.consensusColors[c];
      const bakedIdx = bakedColorAt(c);
      const color = overrideHex
        ? hexToRgbFloat(overrideHex)
        : bakedIdx
          ? hexToRgbFloat(paletteHex(bakedIdx))
          : tabState.consensusTinted
            ? getColorForChar(tabState, ch)
            : [1, 1, 1];
      return { ch, color };
    },
    onEdit: (r, c, clientX, clientY) => {
      const overrideChar = tabState.consensusOverrides[c];
      const current = overrideChar !== undefined ? overrideChar : consensusStr[c] || "-";
      const overrideHex = tabState.consensusColors[c];
      // mirror cellForFn exactly: override -> baked COLOR plane -> tinted/white
      const bakedIdx = bakedColorAt(c);
      const currentColorHex =
        overrideHex ||
        (bakedIdx
          ? paletteHex(bakedIdx)
          : tabState.consensusTinted
            ? rgbFloatToHex(getColorForChar(tabState, current))
            : "#FFFFFF");
      showCellEditPopup(
        clientX,
        clientY,
        current,
        currentColorHex,
        (newChar, newColorHex) => {
          tabState.consensusOverrides[c] = newChar;
          tabState.consensusColors[c] = newColorHex;
          consensusCtl.applyColorOverrides([{ row: 0, col: c, ch: newChar, color: hexToRgbFloat(newColorHex) }]);
        },
        () => {
          delete tabState.consensusColors[c];
          const ch =
            tabState.consensusOverrides[c] !== undefined ? tabState.consensusOverrides[c] : consensusStr[c] || "-";
          const bakedIdx = bakedColorAt(c);
          const color = bakedIdx
            ? hexToRgbFloat(paletteHex(bakedIdx))
            : tabState.consensusTinted
              ? getColorForChar(tabState, ch)
              : [1, 1, 1];
          consensusCtl.applyColorOverrides([{ row: 0, col: c, ch, color }]);
        }
      );
    },
    onHover: (r, c) => handleHover("consensus", r, c),
    onHoverEnd: () => handleHoverEnd()
  });

  tabState._repaintConsensus = () => consensusCtl.rebuildBuffer(); // module-scope helpers can't see consensusCtl, hand them the capability

  function openConsensusOptions() {
    showConsensusOptionsModal(tabState, async (algorithm) => {
      const colCount = getColCount();
      const rowCount = tabState.records.length; // the plane sweep reports ROWS, that's the expensive part now
      const prog = showProgressOverlay("Computing consensus");
      prog.setLabel("Computing consensus…");
      prog.setProgress(0, rowCount);
      await new Promise((r) => setTimeout(r, 50)); // let the overlay paint
      try {
        const onProgress = (done) => prog.setProgress(done, rowCount);
        const chars =
          algorithm === "clustal"
            ? await computeClustalConsensus(tabState, colCount, onProgress)
            : algorithm === "dots"
              ? await computeDotsAndIdentityConsensus(tabState, colCount, onProgress)
              : await computeSimpleConsensusJava(tabState, colCount, onProgress);
        tabState.consensusOverrides = {};
        chars.forEach((ch, c) => {
          tabState.consensusOverrides[c] = ch;
        });
        consensusCtl.rebuildBuffer();
      } finally {
        prog.close();
      }
    });
  }

  const consensusNameLabel = panel.querySelector(".consensus-names .track-row-label");
  consensusNameLabel.style.cursor = "pointer";
  consensusNameLabel.title = "Click to generate consensus";
  consensusNameLabel.addEventListener("click", openConsensusOptions);

  // right-click anywhere on the consensus row also opens the styles picker
  // (left-click on a cell remains the per-cell editor)
  consensusCanvas.addEventListener("contextmenu", (e) => {
    e.preventDefault();
    openConsensusOptions();
  });

  const alignmentCtl = initAlignmentRenderer(alignCanvas, alignPanel, spacer, {
    getRecords: () => tabState.records,
    getColCount,
    getCellDims,
    getLuminance,
    getColor: (r, c, ch) => getShadeColor(tabState, r, c, ch),
    getShadeMode: () => tabState.shadeMode,
    // was: () => { tabState.uniqueColCounts = null; }, that wiped freshly warmed
    // caches on every rebuild. invalidate only when the shade config actually changed.
    recomputeUniqueColors: () => {
      // counts are content; config tweaks are derived live in computeUniqueShadeColor,
      // so this hook guarantees existence and NEVER wipes bc a wipe would force a recount
      if (!tabState.uniqueColCounts || !tabState.uniqueColCounts.cols) tabState.uniqueColCounts = { cols: {}, n: 0 };
    },
    recomputeFrequencyColumns: () => {
      // full shape from birth: computeFrequencyShadeColor reads .counts and .maps
      // unconditionally; config changes are handled inside via cfgKey (remap, no recount)
      if (!tabState.frequencyColumns || !tabState.frequencyColumns.cols)
        tabState.frequencyColumns = { header: frequencyContentHeader(tabState), cols: {}, counts: {}, maps: {}, n: 0 };
    },
    recomputeMatrixColors: () => {
      // never wipe: the warm owns colRef; config tweaks self-heal via the
      // cfgKey stamp inside computeMatrixShadeColor
      if (!tabState.matrixCache || !tabState.matrixCache.colRef)
        tabState.matrixCache = { header: matrixCacheHeader(tabState), colRef: {}, tables: {}, cfgKey: null };
    },
    recomputeClustalXColors: () => {
      tabState.clustalXColors = null;
    },
    onDataChanged: (col, oldCode, newCode) => {
      consensusCache.delete(col); // recompute this column on next read
      if (tabState.consensusCols) tabState.consensusCols[col] = undefined; // inner memo layer too
      const ch =
        tabState.consensusOverrides[col] !== undefined ? tabState.consensusOverrides[col] : consensusStr[col] || "-";
      const overrideHex = tabState.consensusColors[col];
      const color = overrideHex
        ? hexToRgbFloat(overrideHex)
        : tabState.consensusTinted
          ? getColorForChar(tabState, ch)
          : [1, 1, 1];
      consensusCtl.applyColorOverrides([{ row: 0, col, ch, color }]);
      // strips: one column of stats went stale, invalidate just it
      conservationStrip.invalidate(col);
      logoStrip.invalidate(col);
      overviewStrip.invalidate();
      // one column of shade stats went stale, drop just it
      if (tabState.uniqueColCounts && tabState.uniqueColCounts.cols) delete tabState.uniqueColCounts.cols[col];
      if (tabState.frequencyColumns) {
        if (tabState.frequencyColumns.counts) delete tabState.frequencyColumns.counts[col];
        if (tabState.frequencyColumns.maps) delete tabState.frequencyColumns.maps[col];
      }
      if (tabState.clustalXColors && tabState.clustalXColors.cols) delete tabState.clustalXColors.cols[col];
      if (tabState.matrixCache && tabState.matrixCache.colRef) delete tabState.matrixCache.colRef[col];
      if (tabState.consensusBaked) {
        tabState.consensusBaked.chars[col] = 0; // fall back to computed for this column
        if (tabState.consensusBaked.colors) tabState.consensusBaked.colors[col] = 0;
      }
      // keep the retained plane in lockstep: decrement the old char's slot,
      // increment the new one, modal consensus stays instant AND exact
      const lp = tabState.loadPlane;
      if (lp && typeof oldCode === "number" && typeof newCode === "number" && col < lp.cols) {
        const base = col << lp.shift;
        lp.counts[base + (oldCode < 256 ? lp.toDense[oldCode] : lp.otherSlot)]--;
        lp.counts[base + (newCode < 256 ? lp.toDense[newCode] : lp.otherSlot)]++;
      }
      updateHScrollSpacer();
    },
    onDeleteColumns: (lo, hi) => {
      tabState.records.forEach((rec) => {
        if (rec.seqCodes) {
          // clamp the deletion to this row's length since rows can be shorter than
          // the widest row and unclamped typed-array constructs/sets throw
          const L = rec.seqCodes.length;
          if (L > lo) {
            const del = Math.min(hi, L - 1) - lo + 1;
            const next = new Uint8Array(L - del);
            next.set(rec.seqCodes.subarray(0, lo), 0);
            next.set(rec.seqCodes.subarray(Math.min(hi + 1, L)), lo);
            rec.seqCodes = next;
            attachLazyFacade(rec); // keep facades lazy - an eager one here re-inflates every row on each deletion
          }
        } else if (rec.seq.length > lo) {
          rec.seq = rec.seq.slice(0, lo) + rec.seq.slice(hi + 1);
        }
        if (rec.charColors) rec.charColors = reindexColumnMap(rec.charColors, lo, hi);
        if (rec.colorIdx) {
          const L = rec.colorIdx.length;
          if (L > lo) {
            const del = Math.min(hi, L - 1) - lo + 1;
            const next = new Uint16Array(L - del);
            next.set(rec.colorIdx.subarray(0, lo), 0);
            next.set(rec.colorIdx.subarray(Math.min(hi + 1, L)), lo);
            rec.colorIdx = next;
          }
        }
        if (rec.colorPacked) {
          const pack = rec.colorPack;
          const L = pack.cols;
          if (L > lo) {
            const del = Math.min(hi, L - 1) - lo + 1;
            const next = new Uint8Array(Math.ceil(((L - del) * pack.bits) / 8));
            let dst = 0;
            for (let c = 0; c < lo; c++, dst++)
              blimCodeSet(next, dst, pack.bits, blimCodeAt(rec.colorPacked, c, pack.bits));
            for (let c = Math.min(hi + 1, L); c < L; c++, dst++)
              blimCodeSet(next, dst, pack.bits, blimCodeAt(rec.colorPacked, c, pack.bits));
            rec.colorPacked = next;
          }
        }
        if (rec.colorSparse) reindexSparseColorMap(rec.colorSparse, lo, hi);
        if (tabState.colorPack && tabState.colorPack.cols > lo)
          tabState.colorPack.cols -= Math.min(hi, tabState.colorPack.cols - 1) - lo + 1;
        if (tabState.loadPlane) {
          const lp = tabState.loadPlane;
          if (lp.cols > lo) {
            const del = Math.min(hi, lp.cols - 1) - lo + 1;
            const next = new Int32Array((lp.cols - del) << lp.shift);
            next.set(lp.counts.subarray(0, lo << lp.shift), 0);
            next.set(lp.counts.subarray(Math.min(hi + 1, lp.cols) << lp.shift), lo << lp.shift);
            lp.counts = next;
            lp.cols -= del;
          }
        }
      });

      tabState.annotations.forEach((entry) => {
        if (entry.data.length > lo) {
          entry.data = entry.data.slice(0, lo) + entry.data.slice(hi + 1);
        }
        if (entry.colors) entry.colors = reindexColumnMap(entry.colors, lo, hi);
      });
      tabState.consensusOverrides = reindexColumnMap(tabState.consensusOverrides, lo, hi);
      tabState.consensusColors = reindexColumnMap(tabState.consensusColors, lo, hi);

      // lazily reindex the column-keyed caches instead of wiping them: a column's
      // stats don't depend on other columns, so surviving entries stay valid -
      // only their indexes shift. Panning after a delete stays cache-warm.
      reindexColumnCacheMap(consensusCache, lo, hi); // the Proxy's outer memo
      if (tabState.consensusCols) tabState.consensusCols.splice(lo, hi - lo + 1); // inner memo: splice shifts in place
      if (tabState.consensusBaked) {
        // baked planes are typed arrays, same shift, clamped like the row layers
        const shiftPlane = (arr) => {
          if (!arr) return null;
          const L = arr.length;
          if (L <= lo) return arr;
          const del = Math.min(hi, L - 1) - lo + 1;
          const next = new arr.constructor(L - del);
          next.set(arr.subarray(0, lo), 0);
          next.set(arr.subarray(Math.min(hi + 1, L)), lo);
          return next;
        };
        tabState.consensusBaked = {
          chars: shiftPlane(tabState.consensusBaked.chars),
          colors: shiftPlane(tabState.consensusBaked.colors)
        };
      }
      if (tabState.uniqueColCounts && tabState.uniqueColCounts.cols)
        tabState.uniqueColCounts.cols = reindexColumnMap(tabState.uniqueColCounts.cols, lo, hi);
      if (tabState.frequencyColumns) {
        if (tabState.frequencyColumns.counts)
          tabState.frequencyColumns.counts = reindexColumnMap(tabState.frequencyColumns.counts, lo, hi);
        if (tabState.frequencyColumns.maps)
          tabState.frequencyColumns.maps = reindexColumnMap(tabState.frequencyColumns.maps, lo, hi);
      }
      if (tabState.matrixCache && tabState.matrixCache.colRef)
        tabState.matrixCache.colRef = reindexColumnMap(tabState.matrixCache.colRef, lo, hi);
      if (tabState.clustalXColors && tabState.clustalXColors.cols)
        tabState.clustalXColors.cols = reindexColumnMap(tabState.clustalXColors.cols, lo, hi);
      // strips reindex their column caches too; the overview strip stays wholesale
      // (its raster thumbnail is stale as a whole, not per column)
      conservationStrip.reindex(lo, hi);
      logoStrip.reindex(lo, hi);
      overviewStrip.invalidate();
      invalidateMotifCaches(); // regex/scanprosite hit coordinates stay dropped, revert semantics are positional
      annotationCtl.rebuildBuffer();
      numberingCtl.rebuildBuffer();
      consensusCtl.rebuildBuffer();
      updateHScrollSpacer();
    },
    onAnnotateColumns: (lo, hi, onModalClose) => {
      showAnnotateSelectionModal(tabState, lo, hi, () => annotationCtl.rebuildBuffer(), onModalClose);
    },
    onBlockShadeColumns: (lo, hi, onModalClose) => {
      showBlockShadingModal(
        lo,
        hi,
        [
          {
            name: "(Annotations)",
            rowCount: tabState.annotations.length,
            getColor: (r, c) => {
              const ann = tabState.annotations[r];
              return (ann.colors && ann.colors[c]) || rgbFloatToHex(ANNOTATION_BG);
            },
            setColor: (r, c, hex) => {
              const ann = tabState.annotations[r];
              if (!ann.colors) ann.colors = {};
              ann.colors[c] = hex;
            },
            apply: (hits) => annotationCtl.applyColorOverrides(hits)
          },
          {
            name: "(Sequences)",
            rowCount: tabState.records.length,
            getColor: (r, c) => {
              const rec = tabState.records[r];
              const codes = rec.seqCodes;
              const ch = codes ? (c < codes.length ? charOfCode(codes[c]) : "-") : rec.seq[c] || "-"; // codes-first - the Reset snapshot walks every row
              return recordColorAt(rec, c) || rgbFloatToHex(getShadeColor(tabState, r, c, ch));
            },
            setColor: (r, c, hex) => {
              setRecordColor(tabState.records[r], c, hex);
            },
            apply: (hits) => alignmentCtl.applyColorOverrides(hits)
          },
          {
            name: "(Consensus)",
            rowCount: 1,
            getColor: (r, c) => tabState.consensusColors[c] || "#FFFFFF",
            setColor: (r, c, hex) => {
              tabState.consensusColors[c] = hex;
            },
            apply: (hits) => consensusCtl.applyColorOverrides(hits)
          }
        ],
        onModalClose
      );
    },
    onGenerateLogo: (lo, hi) => {
      showSeqLogoOptionsModal(tabState, (opts) => {
        showSequenceLogoWindow(tabState, hi - lo + 1, { ...opts, colOffset: lo });
      });
    },
    onExportColumns: (lo, hi) => exportColumnsAsNewTab(lo, hi),
    onAutoScrollDelta: (delta) => {
      hScrollTrack.scrollLeft += delta * hScrollScale;
    },
    onCopyColumns: (lo, hi) => {
      const text = tabState.records
        .map((rec) => {
          const codes = rec.seqCodes; // codes-first - rec.seq would fire the lazy facade on every row
          const slice = codes
            ? SEQ_FACADE_DECODER.decode(codes.subarray(lo, Math.min(codes.length, hi + 1)))
            : rec.seq.slice(lo, hi + 1);
          return ">" + rec.header + "\n" + slice;
        })
        .join("\n");
      const done = () => {
        hoverInfoEl.textContent = `Copied columns ${lo + 1}\u2013${hi + 1} (${tabState.records.length} sequences)`;
      };
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(done, () => {
          // iframe / non-secure-context fallback
          const ta = document.createElement("textarea");
          ta.value = text;
          document.body.appendChild(ta);
          ta.select();
          document.execCommand("copy");
          ta.remove();
          done();
        });
      } else {
        const ta = document.createElement("textarea");
        ta.value = text;
        document.body.appendChild(ta);
        ta.select();
        document.execCommand("copy");
        ta.remove();
        done();
      }
    },
    onSelectionChange: (lo, hi) => {
      annotationCtl.setSelection(lo, hi);
      numberingCtl.setSelection(lo, hi);
      consensusCtl.setSelection(lo, hi);
    },
    onHover: (r, c) => handleHover("alignment", r, c),
    onHoverEnd: () => handleHoverEnd(),
    recomputeFrequencyColumns: () => {
      tabState.frequencyColumns = null;
    },
    recomputeSequenceColors: () => {
      tabState.sequenceCache = null;
    }
  });

  console.log("[createTab] renderer up");

  // dismiss column selection AND its popup on any interaction outside the selection drag
  panel.addEventListener(
    "pointerdown",
    (e) => {
      if (e.target.closest && e.target.closest(".context-menu, .cell-edit-popup, .modal-overlay")) return;
      if (window._activeContextMenu && e.target !== alignCanvas) closeContextMenu();
      if (e.button === 0 && e.target !== alignCanvas) alignmentCtl.clearSelection();
    },
    true
  );
  hScrollTrack.addEventListener(
    "scroll",
    () => {
      if (alignmentCtl.isSelecting()) return;
      if (window._activeContextMenu) closeContextMenu();
      alignmentCtl.clearSelection();
    },
    { passive: true }
  );
  alignPanel.addEventListener(
    "scroll",
    () => {
      if (alignmentCtl.isSelecting()) return;
      if (window._activeContextMenu) closeContextMenu();
      alignmentCtl.clearSelection();
    },
    { passive: true }
  );

  const allTrackCtls = [annotationCtl, numberingCtl, alignmentCtl, consensusCtl];

  // the strip initializers return destroy functions, hold on to them so
  // closeTab can stop their interval timers instead of leaking them
  // Mini strips (overview / conservation / logo)
  // created BEFORE the alignment renderer: its onDataChanged / onDeleteColumns
  // closures call these strips' invalidate(), so the handles must exist by the
  // time initAlignmentRenderer's config object is built
  const overviewStrip = initOverviewStrip({
    tabState,
    stripEl: overviewStripEl,
    canvasEl: overviewCanvas,
    markerEl: overviewMarker,
    connectorsSvg: overviewSvg,
    polygon: overviewPolygon,
    contentColumnEl,
    alignPanel,
    hScrollTrack,
    consensusContentEl,
    getColCount,
    getCellDims,
    realHScroll,
    realVScroll, // <- updateOverlay/jumpTo now call these through cfg
    setRealVScroll,
    getHScrollScale: () => hScrollScale,
    isActive: () => panel.classList.contains("active")
  });
  const conservationStrip = initConservationStrip({
    tabState,
    stripEl: conservationStripEl,
    canvasEl: conservationCanvas,
    alignPanel,
    hScrollTrack,
    getColCount,
    getCellDims,
    realHScroll,
    consensusCache,
    isActive: () => panel.classList.contains("active")
  });
  const logoStrip = initLogoStrip({
    tabState,
    stripEl: logoStripEl,
    canvasEl: logoCanvas,
    alignPanel,
    hScrollTrack,
    getColCount,
    getCellDims,
    realHScroll,
    isActive: () => panel.classList.contains("active")
  });
  const stripDestroyers = [overviewStrip, conservationStrip, logoStrip];

  console.log("[createTab] strips up");

  const ro = new ResizeObserver(() => {
    if (!panel.classList.contains("active")) return; // hidden panels are 0-sized; they re-sync on activation
    updateAlignmentHeight();
    allTrackCtls.forEach((ctl) => ctl.onResize());
  });
  ro.observe(alignPanel);

  tabRenderers.set(tabId, {
    tabState,
    ctls: allTrackCtls,
    ac,
    stripDestroyers,
    ro,
    onActivate: () => {
      updateAlignmentHeight();
      allTrackCtls.forEach((ctl) => ctl.onResize());
    }
  });

  let pendingRebuild = null;
  function scheduleRebuild() {
    if (pendingRebuild) return;
    pendingRebuild = requestAnimationFrame(() => {
      pendingRebuild = null;
      alignmentCtl.rebuildBuffer();
    });
  }

  // Cross-track hover: highlight column in all tracks + info readout
  function handleHover(trackType, row, col) {
    let rowLabel;
    if (trackType === "alignment") rowLabel = `seq ${row + 1}`;
    else if (trackType === "annotation") rowLabel = `ann ${row + 1}`;
    else if (trackType === "numbering") rowLabel = "position";
    else rowLabel = "consensus";
    hoverInfoEl.textContent = `(${rowLabel}, col ${col + 1})`;
    allTrackCtls.forEach((ctl) => ctl.setHoverCol(col));
    alignmentCtl.setHoverRow(trackType === "alignment" ? row : -1);
  }
  function handleHoverEnd() {
    hoverInfoEl.textContent = "";
    allTrackCtls.forEach((ctl) => ctl.setHoverCol(-1));
    alignmentCtl.setHoverRow(-1);
  }

  // Annotation names (editable, with 5 actions)
  function defaultAnnotationName(n) {
    return `(Annotations_${n})`;
  }

  function rebuildAnnotationNames() {
    annotationNamesEl.innerHTML = "";
    tabState.annotations.forEach((ann, i) => {
      annotationNamesEl.appendChild(buildAnnotationNameRow(ann, i));
    });
    applyFixedHeights();
  }

  function buildAnnotationNameRow(ann, index) {
    const row = document.createElement("div");
    row.className = "name-row";

    const text = document.createElement("span");
    text.className = "name-text";
    text.textContent = ann.name;
    text.title = "Double-click to rename";
    text.addEventListener("dblclick", (e) => {
      e.stopPropagation();
      text.contentEditable = "true";
      text.focus();
      document.execCommand("selectAll", false, null);
    });
    text.addEventListener("blur", () => {
      text.contentEditable = "false";
      const trimmed = text.textContent.trim();
      ann.name = trimmed ? `(${trimmed.replace(/^\(|\)$/g, "")})` : defaultAnnotationName(index + 1);
      text.textContent = ann.name;
    });
    text.addEventListener("keydown", (e) => {
      if (e.key === "Enter") {
        e.preventDefault();
        text.blur();
      }
    });

    const btns = document.createElement("span");
    btns.className = "row-btns";

    const addBtn = mkBtn("\u2795", "Add annotation row below", () => {
      const n = tabState.annotations.length + 1;
      tabState.annotations.splice(index + 1, 0, { name: defaultAnnotationName(n), data: "", colors: {} });
      rebuildAnnotationNames();
      annotationCtl.onRowCountChanged();
      updateAlignmentHeight();
    });
    const upBtn = mkBtn("\u25B2", "Move up one row", () => {
      if (index > 0) {
        const tmp = tabState.annotations[index - 1];
        tabState.annotations[index - 1] = tabState.annotations[index];
        tabState.annotations[index] = tmp;
        rebuildAnnotationNames();
        annotationCtl.rebuildBuffer();
      }
    });
    const topBtn = mkBtn("\u2912", "Move to top", () => {
      const [item] = tabState.annotations.splice(index, 1);
      tabState.annotations.unshift(item);
      rebuildAnnotationNames();
      annotationCtl.rebuildBuffer();
    });
    const bottomBtn = mkBtn("\u2913", "Move to bottom", () => {
      const [item] = tabState.annotations.splice(index, 1);
      tabState.annotations.push(item);
      rebuildAnnotationNames();
      annotationCtl.rebuildBuffer();
    });
    const deleteBtn = mkBtn("🗑", "Delete annotation row", () => {
      if (tabState.annotations.length <= 1) {
        showLastRowModal("annotation");
        return;
      }
      showConfirmDeleteModal(`annotation row "${ann.name}"`, () => {
        tabState.annotations.splice(index, 1);
        rebuildAnnotationNames();
        annotationCtl.onRowCountChanged();
        updateAlignmentHeight();
      });
    });
    deleteBtn.classList.add("delete-btn");

    btns.append(addBtn, upBtn, topBtn, bottomBtn, deleteBtn);
    row.append(text, btns);
    return row;
  }
  rebuildAnnotationNames();

  //  Confirm-delete modal
  function showConfirmDeleteModal(label, onConfirm) {
    const overlay = document.createElement("div");
    overlay.className = "modal-overlay";
    const box = document.createElement("div");
    box.className = "modal-box shade-modal";
    box.innerHTML = `<h3>Delete ${label}?</h3>`;

    const msgRow = document.createElement("div");
    msgRow.className = "shade-row";
    msgRow.textContent = "This cannot be undone.";
    box.appendChild(msgRow);

    const btnRow = document.createElement("div");
    btnRow.className = "shade-row";

    const deleteBtn = document.createElement("button");
    deleteBtn.textContent = "Delete";
    deleteBtn.className = "modal-close-btn";
    deleteBtn.addEventListener("click", () => {
      overlay.remove();
      onConfirm();
    });

    const cancelBtn = document.createElement("button");
    cancelBtn.textContent = "Cancel";
    cancelBtn.className = "modal-close-btn";
    cancelBtn.addEventListener("click", () => overlay.remove());

    btnRow.append(deleteBtn, cancelBtn);
    box.appendChild(btnRow);

    overlay.appendChild(box);
    overlay.addEventListener("click", (e) => {
      if (e.target === overlay) overlay.remove(); // clicking outside = cancel
    });
    document.body.appendChild(overlay);
  }

  // Last-row delete rejection modal
  function showLastRowModal(kind) {
    const label = kind === "annotation" ? "annotation row" : "sequence";
    const overlay = document.createElement("div");
    overlay.className = "modal-overlay";
    const box = document.createElement("div");
    box.className = "modal-box shade-modal";
    box.innerHTML = `<h3>Can't delete</h3>`;

    const msgRow = document.createElement("div");
    msgRow.className = "shade-row";
    msgRow.textContent = `This is your last ${label}, and at least one is required. It can't be deleted.`;
    box.appendChild(msgRow);

    const btnRow = document.createElement("div");
    btnRow.className = "shade-row";
    const okBtn = document.createElement("button");
    okBtn.textContent = "OK";
    okBtn.className = "modal-close-btn";
    okBtn.addEventListener("click", () => overlay.remove());
    btnRow.appendChild(okBtn);
    box.appendChild(btnRow);

    overlay.appendChild(box);
    overlay.addEventListener("click", (e) => {
      if (e.target === overlay) overlay.remove();
    });
    document.body.appendChild(overlay);
  }

  // Sequence names panel
  function refreshAfterRecordsChanged(opts) {
    refreshConsensus(); // clears both consensus cache layers, rows changed, every column's stats are stale
    if (!opts || !opts.keepConsensus) tabState.consensusBaked = null; // reorder changes neither column counts nor the consensus they imply
    conservationStrip.invalidate();
    logoStrip.invalidate();
    overviewStrip.invalidate();
    invalidateMotifCaches(); // hitsByRow/appliedHits are row-index keyed
    // row-coordinate caches: sequence/matrix headers cache refIndex; the frequency
    // header caches seqNum; unique counts are computed over the row set
    tabState.sequenceCache = null;
    tabState.matrixCache = null;
    tabState.frequencyColumns = null;
    tabState.uniqueColCounts = null;
    // row membership normally changes counts, but callers that adjust the plane
    // exactly (delete's row-delta) pass keepPlane so warmups stay instant
    if (!opts || !opts.keepPlane) tabState.loadPlane = null;
    consensusCtl.rebuildBuffer();
    numberingCtl.rebuildBuffer();
    alignmentCtl.rebuildBuffer();
    updateHScrollSpacer(); // refreshes both horizontal and vertical compressed spacers
    updateAlignmentHeight();
    updateHScrollSpacer(); // viewport height may have changed, so refresh mapping once more
    alignmentCtl.onScroll(realVScroll(), realHScroll());
    buildNamesPanel(namesPanel, tabState, refreshAfterRecordsChanged);
  }
  buildNamesPanel(namesPanel, tabState, refreshAfterRecordsChanged);

  // Scroll sync
  let syncingV = false;

  function syncVerticalFrom(source) {
    if (syncingV) return;
    syncingV = true;

    // Both panels have the same compressed physical geometry, so physical
    // scrollTop copies exactly. The renderer receives the logical value.
    const target = source === alignPanel ? namesPanel : alignPanel;
    target.scrollTop = source.scrollTop;

    alignmentCtl.onScroll(realVScroll(), realHScroll());
    renderNameWindow(namesPanel, tabState, refreshAfterRecordsChanged, true);

    syncingV = false;
  }

  namesPanel.addEventListener("scroll", () => syncVerticalFrom(namesPanel), { passive: true });
  alignPanel.addEventListener("scroll", () => syncVerticalFrom(alignPanel), { passive: true });
  hScrollTrack.addEventListener("scroll", () => {
    const left = realHScroll();
    alignmentCtl.onScroll(realVScroll(), left); // logical vertical, not raw scrollTop
    annotationCtl.onScroll(left);
    numberingCtl.onScroll(left);
    consensusCtl.onScroll(left);
  });

  alignPanel.addEventListener(
    "wheel",
    (e) => {
      if (e.ctrlKey || e.metaKey) {
        // Ctrl+wheel / trackpad pinch: font-size zoom anchored at the pointer,
        // so the character under the mouse stays under the mouse
        e.preventDefault();
        const dir = e.deltaY < 0 ? 1 : -1;
        const next = Math.max(6, Math.min(40, tabState.fontSize + dir));
        if (next === tabState.fontSize) return;

        // capture the fractional cell coordinate under the pointer, pre-zoom
        const rect = alignPanel.getBoundingClientRect();
        const mx = e.clientX - rect.left;
        const my = e.clientY - rect.top;
        const dims = getCellDims();
        const anchorCol = (realHScroll() + mx) / dims.w;
        const anchorRow = (realVScroll() + my) / dims.h;

        tabState.fontSize = next;
        fontSizeInput.value = next;
        fontSizeLabel.textContent = `${next}px`;
        applyFontSize(); // synchronous: geometry must be live before the anchor math below

        // re-place the anchor point under the pointer, post-zoom
        const d2 = getCellDims();
        setRealHScroll(anchorCol * d2.w - mx);
        setRealVScroll(Math.max(0, anchorRow * d2.h - my));
        return;
      }
      if (e.deltaX !== 0) {
        e.preventDefault();
        hScrollTrack.scrollLeft += e.deltaX * hScrollScale;
      } else if (e.shiftKey && e.deltaY !== 0) {
        e.preventDefault();
        hScrollTrack.scrollLeft += e.deltaY * hScrollScale;
      }
    },
    { passive: false }
  );
  let touchStartX = null;
  let touchStartY = null;
  let touchStartScrollLeft = 0;
  let touchStartScrollTop = 0;
  let touchDirection = null; // null -> undecided, "h" -> horizontal, "v" -> vertical

  alignPanel.addEventListener("touchstart", (e) => {
    touchStartX = e.touches[0].clientX;
    touchStartY = e.touches[0].clientY;
    touchStartScrollLeft = hScrollTrack.scrollLeft;
    touchStartScrollTop = alignPanel.scrollTop;
    touchStartRealV = realVScroll(); // captured once, here, not per move
    touchDirection = null;
  });

  alignPanel.addEventListener(
    "touchmove",
    (e) => {
      if (touchStartX === null) return;
      const dx = touchStartX - e.touches[0].clientX;
      const dy = touchStartY - e.touches[0].clientY;
      if (touchDirection === null) {
        if (Math.abs(dx) < 8 && Math.abs(dy) < 8) return; // wait for a clear direction
        touchDirection = Math.abs(dx) > Math.abs(dy) ? "h" : "v";
      }
      if (touchDirection === "h") {
        hScrollTrack.scrollLeft = touchStartScrollLeft + dx * hScrollScale;
      } else {
        setRealVScroll(touchStartRealV + dy); // logical start + physical finger delta
      }
      e.preventDefault();
    },
    { passive: false }
  );

  alignPanel.addEventListener("touchend", () => {
    touchStartX = null;
    touchDirection = null;
  });
  // Divider drag
  let dragging = false;
  dividerEl.addEventListener("mousedown", (e) => {
    dragging = true;
    dividerEl.classList.add("dragging");
    e.preventDefault();
  });
  dividerEl.addEventListener(
    "touchstart",
    (e) => {
      dragging = true;
      dividerEl.classList.add("dragging");
      e.preventDefault();
    },
    { passive: false }
  );

  window.addEventListener(
    "touchmove",
    (e) => {
      if (!dragging) return;
      const containerRect = panel.querySelector(".msa-container").getBoundingClientRect();
      let newWidth = e.touches[0].clientX - containerRect.left;
      newWidth = Math.max(60, Math.min(newWidth, containerRect.width - 100));
      namesColumn.style.width = `${newWidth}px`;
      e.preventDefault();
    },
    { passive: false, signal }
  );

  window.addEventListener(
    "touchend",
    () => {
      if (dragging) {
        dragging = false;
        dividerEl.classList.remove("dragging");
        allTrackCtls.forEach((ctl) => ctl.onResize());
      }
    },
    { signal }
  );
  // Window resize
  window.addEventListener(
    "resize",
    () => {
      if (!panel.classList.contains("active")) return; // hidden tabs have zero-size layout; they re-sync on activation
      updateAlignmentHeight();
      allTrackCtls.forEach((ctl) => ctl.onResize());
    },
    { signal }
  );

  window.addEventListener(
    "keydown",
    (e) => {
      if (!(e.ctrlKey || e.metaKey) || e.key.toLowerCase() !== "g") return;
      if (!panel.classList.contains("active")) return;
      if (e.target.closest && e.target.closest("input, textarea, [contenteditable]")) return;
      e.preventDefault(); // suppress the browser's find-next
      showGotoColumnModal();
    },
    { signal }
  );

  window.addEventListener(
    "mousemove",
    (e) => {
      if (!dragging) return;
      const containerRect = panel.querySelector(".msa-container").getBoundingClientRect();
      let newWidth = e.clientX - containerRect.left;
      newWidth = Math.max(60, Math.min(newWidth, containerRect.width - 100));
      namesColumn.style.width = `${newWidth}px`;
    },
    { signal }
  );
  window.addEventListener(
    "mouseup",
    () => {
      if (dragging) {
        dragging = false;
        dividerEl.classList.remove("dragging");
        allTrackCtls.forEach((ctl) => ctl.onResize());
      }
    },
    { signal }
  );

  // Settings wiring
  const fontSizeInput = panel.querySelector(".fontSizeInput");
  const fontSizeLabel = panel.querySelector(".fontSizeLabel");
  const luminanceInput = panel.querySelector(".luminanceInput");
  const luminanceLabel = panel.querySelector(".luminanceLabel");
  const alphaBtns = panel.querySelectorAll(".alphaBtn");
  const fileMenuBtn = panel.querySelector(".fileMenuBtn");
  const shadeMenuBtn = panel.querySelector(".shadeMenuBtn");

  fontSizeInput.value = tabState.fontSize;
  fontSizeLabel.textContent = `${tabState.fontSize}px`;
  luminanceInput.value = tabState.luminance;
  luminanceLabel.textContent = tabState.luminance.toFixed(3);

  function applyFontSize() {
    const { w, h } = getCellDims();
    applyCssVars();
    applyFixedHeights();
    allTrackCtls.forEach((ctl) => ctl.setCellSize(w, h));
    updateHScrollSpacer();
    updateAlignmentHeight();
  }

  fontSizeInput.addEventListener("input", (e) => {
    const size = Number(e.target.value);
    fontSizeLabel.textContent = `${size}px`;
    tabState.fontSize = size;
    applyFontSize();
  });

  // first-time luminance guard: warn before the slider can be dragged (once per page load)
  const luminanceGuard = (e) => {
    if (luminanceAcked) return;
    e.preventDefault();
    e.stopPropagation();
    showLuminanceWarningModal(() => {
      luminanceAcked = true;
    });
  };
  luminanceInput.addEventListener("pointerdown", luminanceGuard);
  luminanceInput.addEventListener("keydown", luminanceGuard);

  luminanceInput.addEventListener("input", (e) => {
    const val = Number(e.target.value);
    luminanceLabel.textContent = val.toFixed(3);
    tabState.luminance = val;
    allTrackCtls.forEach((ctl) => ctl.setLuminance(val));
  });

  function setAlphabet(val) {
    tabState.alphabet = val;
    alphaBtns.forEach((b) => b.classList.toggle("active", b.dataset.val === val));
    alignmentCtl.rebuildBuffer();
    consensusCtl.rebuildBuffer();
  }
  alphaBtns.forEach((b) => b.addEventListener("click", () => setAlphabet(b.dataset.val)));
  setAlphabet(tabState.alphabet);

  function getTabDisplayName() {
    return nameSpan.textContent || "alignment";
  }

  // File menu
  fileMenuBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    showDropdown(fileMenuBtn, [
      {
        label: "Export to FASTA",
        onClick: () => {
          if (virtualGate(tabState, "Export")) return; // Phase 2: stream through the pager
          exportFastaStreaming(tabState.records, getTabDisplayName() + ".fasta");
        }
      },
      {
        label: "Save as project",
        onClick: () => {
          if (virtualGate(tabState, "Export")) return;
          const colCount = getColCount();
          const saveSlim = () =>
            exportSlimStreaming(
              tabState,
              colCount,
              (r, c, ch) => {
                const rec = tabState.records[r];
                const override = recordColorAt(rec, c);
                return override || rgbFloatToHex(getShadeColor(tabState, r, c, ch));
              },
              (r, c) => {
                const ann = tabState.annotations[r];
                const override = ann.colors && ann.colors[c];
                return override || rgbFloatToHex(ANNOTATION_BG);
              },
              (c) => {
                const overrideChar = tabState.consensusOverrides[c];
                const ch = overrideChar !== undefined ? overrideChar : consensusStr[c] || "-";
                const bakedIdx = bakedColorAt(c);
                const overrideHex =
                  tabState.consensusColors[c] !== undefined
                    ? tabState.consensusColors[c]
                    : bakedIdx
                      ? paletteHex(bakedIdx)
                      : undefined;
                const bgHex = overrideHex || "#FFFFFF";
                return { ch, bgHex };
              },
              getTabDisplayName() + ".slim"
            );
          showSaveProjectModal(
            () =>
              exportBlimStreaming(
                tabState,
                colCount,
                (r, c, ch) => {
                  const rec = tabState.records[r];
                  const override = recordColorAt(rec, c);
                  return override || rgbFloatToHex(getShadeColor(tabState, r, c, ch));
                },
                (r, c) => {
                  const ann = tabState.annotations[r];
                  const override = ann.colors && ann.colors[c];
                  return override || rgbFloatToHex(ANNOTATION_BG);
                },
                (c) => {
                  const overrideChar = tabState.consensusOverrides[c];
                  const ch = overrideChar !== undefined ? overrideChar : consensusStr[c] || "-";
                  const bakedIdx = bakedColorAt(c);
                  const overrideHex =
                    tabState.consensusColors[c] !== undefined
                      ? tabState.consensusColors[c]
                      : bakedIdx
                        ? paletteHex(bakedIdx)
                        : undefined;
                  const bgHex = overrideHex || "#FFFFFF";
                  return { ch, bgHex };
                },
                getTabDisplayName() + ".blim"
              ),
            saveSlim
          );
        }
      },
      {
        label: "Output to RTF",
        onClick: () =>
          showRtfExportModal(tabState, (opts) => {
            const colCount = getColCount();
            const prog = showProgressOverlay("Saving RTF");
            withTextSink(getTabDisplayName() + ".rtf", "application/rtf", ".rtf", (sink) =>
              generateRtfV2(
                tabState,
                colCount,
                (r, c, ch) => {
                  const rec = tabState.records[r];
                  const override = recordColorAt(rec, c);
                  return override || rgbFloatToHex(getShadeColor(tabState, r, c, ch));
                },
                (r, c, ch) => {
                  const ann = tabState.annotations[r];
                  const override = ann.colors && ann.colors[c];
                  return override || rgbFloatToHex(ANNOTATION_BG);
                },
                (c) => {
                  const overrideChar = tabState.consensusOverrides[c];
                  const ch = overrideChar !== undefined ? overrideChar : consensusStr[c] || "-";
                  const bakedIdx = bakedColorAt(c);
                  const overrideHex =
                    tabState.consensusColors[c] !== undefined
                      ? tabState.consensusColors[c]
                      : bakedIdx
                        ? paletteHex(bakedIdx)
                        : undefined;
                  const bgHex = overrideHex || "#FFFFFF";
                  return { ch, bgHex };
                },
                opts,
                sink,
                prog
              )
            )
              .catch((err) => {
                console.error("RTF export failed:", err);
                alert("RTF export failed: " + err.message);
              })
              .finally(() => prog.close());
          })
      },
      {
        label: "Print preview",
        onClick: () => {
          const colCount = getColCount();
          showPrintPreviewModal(
            tabState,
            colCount,
            (r, c, ch) => {
              const rec = tabState.records[r];
              const override = recordColorAt(rec, c);
              return override || rgbFloatToHex(getShadeColor(tabState, r, c, ch));
            },
            (r, c) => {
              const ann = tabState.annotations[r];
              const override = ann.colors && ann.colors[c];
              return override || rgbFloatToHex(ANNOTATION_BG);
            },
            (c) => {
              const overrideChar = tabState.consensusOverrides[c];
              const ch = overrideChar !== undefined ? overrideChar : consensusStr[c] || "-";
              const bakedIdx = bakedColorAt(c);
              const overrideHex =
                tabState.consensusColors[c] !== undefined
                  ? tabState.consensusColors[c]
                  : bakedIdx
                    ? paletteHex(bakedIdx)
                    : undefined;
              const bgHex = overrideHex || "#FFFFFF";
              return { ch, bgHex };
            },
            getTabDisplayName()
          );
        }
      },
      {
        label: "Go to column",
        onClick: showGotoColumnModal
      },
      {
        label: "Viewport",
        onClick: () =>
          showViewportModal(tabState, {
            getColCount,
            getCellDims,
            getHScrollScale: () => hScrollScale,
            realHScroll,
            realVScroll,
            setRealVScroll,
            hScrollTrack,
            alignPanel
          })
      },
      { label: "Dereplicate", onClick: () => runDereplication(tabState, refreshAfterRecordsChanged) }
    ]);
  });

  // Shade menu
  shadeMenuBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    const shadeCtx = {
      rebuildAlignment: scheduleRebuild,
      rebuildAfterReorder: () => {
        buildNamesPanel(namesPanel, tabState, refreshAfterRecordsChanged);
        refreshAfterRecordsChanged({ keepPlane: true, keepConsensus: true }); // sort is a permutation too
      },
      setShadeMode,
      applyColorOverrides: alignmentCtl.applyColorOverrides,
      visibleColumnRange: () => {
        // mirror the renderer's buffered window: viewport + one viewport of margin each side
        const { w } = getCellDims();
        const view = Math.ceil(alignPanel.clientWidth / w) + 1;
        const first = Math.min(Math.max(0, getColCount() - 1), Math.max(0, Math.floor(realHScroll() / w)));
        return { lo: Math.max(0, first - view), hi: Math.min(getColCount(), first + 2 * view) };
      },
      invalidateStrips: () => {
        // pull the strips' stat rebuilds into the warmup window instead of
        // letting them land on the user's first slider touch
        conservationStrip.invalidate();
        logoStrip.invalidate();
        overviewStrip.invalidate();
      }
    };
    // virtual tabs: a paged row arriving from disk makes placeholder cells real -
    // repaint. Every read path (colCodeAt -> facade -> peekRow) kicks its own fetch;
    // this is the only callback the pager needs.
    if (tabState.virtual)
      tabState.virtual.onMiss = () => {
        scheduleRebuild();
        overviewStrip.invalidate(); // now safe: strips only paint resident pages
      };
    const mark = () => ""; // actions, not state, no checkmarks
    const isNucleotide = tabState.alphabet === "nucleotide";
    showDropdown(shadeMenuBtn, [
      {
        label: "Clear shading",
        onClick: () => {
          tabState.consensusTinted = false;
          tabState.shadeCleared = true; // sequences render white via getShadeColor
          tabState.records.forEach((rec) => {
            rec.colorIdx = null;
            rec.colorPacked = null; // baked .blim color plane
            rec.colorSparse = null; // painted layer on top of packed
          });
          tabState.annotations.forEach((ann) => {
            ann.colors = {};
          });
          tabState.consensusColors = {};
          if (tabState.consensusBaked) tabState.consensusBaked.colors = null; // baked consensus plane rides along
          const sp = tabState.shadeConfig.scanprosite,
            rx = tabState.shadeConfig.regex;
          sp.hitsByRow = null;
          sp.appliedHits = [];
          rx.hitsByRow = null;
          rx.appliedHits = [];
          annotationCtl.rebuildBuffer();
          consensusCtl.rebuildBuffer();
          alignmentCtl.rebuildBuffer();
        }
      },
      "divider",
      {
        label: "Edit color scheme",
        onClick: () => {
          showColorSchemeModal(tabState, () => {
            scheduleRebuild();
            consensusCtl.rebuildBuffer();
          });
        }
      },
      "divider",
      {
        label: mark("standard") + "Standard",
        onClick: () => {
          tabState.consensusTinted = true;
          shadeCtx.setShadeMode("standard");
        }
      },
      {
        label: mark("clustalx") + "ClustalX",
        disabled: isNucleotide,
        title: isNucleotide ? "Protein alignments only" : "",
        onClick: () => {
          shadeCtx.setShadeMode("clustalx");
        }
      },
      {
        label: mark("frequency") + "Shade by frequency",
        onClick: () => {
          showFrequencyShadeModal(tabState, shadeCtx);
        }
      },
      {
        label: mark("unique") + "Shade unique",
        onClick: () => {
          showUniqueShadeModal(tabState, shadeCtx);
        }
      },
      {
        label: mark("matrix") + "Substitution matrix",
        disabled: isNucleotide,
        title: isNucleotide ? "Protein alignments only" : "",
        onClick: () => {
          showMatrixShadeModal(tabState, shadeCtx);
        }
      },
      {
        label: mark("sequence") + "Shade by sequence",
        onClick: () => {
          showSequenceShadeModal(tabState, shadeCtx);
        }
      },
      "divider",
      {
        label: mark("regex") + "Regex-based",
        onClick: () => {
          showRegexShadeModal(tabState, shadeCtx);
        }
      },
      {
        label: mark("scanprosite") + "ScanProsite-based",
        disabled: isNucleotide,
        title: isNucleotide ? "Protein alignments only" : "",
        onClick: () => {
          showScanPrositeConfirmModal(() => {
            runScanPrositeShading(tabState, shadeCtx);
          });
        }
      }
    ]);
  });

  closeBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    closeTab(tabId, btn);
  });

  updateHScrollSpacer();
  updateAlignmentHeight();
  updateHScrollSpacer();
  alignmentCtl.onScroll(realVScroll(), realHScroll());

  console.log("[createTab] complete");

  return { refreshAfterRecordsChanged, tabState }; // tabState lets callers operate on the exact array the tab renders
}

// tab limit used to be 4 prior to this; suspend inacive tabs
function activateTab(tabId, btnEl) {
  // free the outgoing tab's GL contexts before switching, browsers cap the
  // number of live WebGL contexts per page to 4 and evict the oldest past it
  const prevPanel = document.querySelector(".tab-panel.active");
  if (prevPanel && prevPanel.id !== tabId) {
    const prevEntry = tabRenderers.get(prevPanel.id);
    if (prevEntry) prevEntry.ctls.forEach((ctl) => ctl.suspend());
  }
  document.querySelectorAll(".tab-btn").forEach((b) => b.classList.remove("active"));
  document.querySelectorAll(".tab-panel").forEach((p) => p.classList.remove("active"));
  document.getElementById(tabId).classList.add("active");
  btnEl.classList.add("active");
  const entry = tabRenderers.get(tabId);
  if (entry) {
    entry.ctls.forEach((ctl) => ctl.resume());
    // the panel was display:none, so window resizes while it was hidden left
    // its canvases stale or zero-sized, re-measure and repaint now that it's visible
    entry.onActivate();
  }
}

function closeTab(tabId, btnEl) {
  const panel = document.getElementById(tabId);
  const wasActive = btnEl.classList.contains("active");
  const entry = tabRenderers.get(tabId);
  if (entry) {
    entry.ctls.forEach((ctl) => ctl.suspend());
    if (entry.ac) entry.ac.abort();
    entry.stripDestroyers.forEach((s) => s && s.destroy && s.destroy()); // strip controllers: { destroy, invalidate, reindex } - destroy() clears their setInterval timers
    if (entry.ro) entry.ro.disconnect();
    tabRenderers.delete(tabId);
    // sever the payload - any stray closure now holds empty containers, not gigabytes of typed arrays
    if (entry.tabState) {
      entry.tabState.records.length = 0;
      entry.tabState.records.push({ id: 0, header: "", seq: "" }); // benign shape for late callbacks
      entry.tabState.annotations.length = 0;
      entry.tabState.consensusBaked = null;
      entry.tabState.loadPlane = null;
      entry.tabState.colorPack = null;
      entry.tabState.virtual = null; // releases the paged File reference too
    }
  }
  btnEl.remove();
  panel.remove();
  if (wasActive) {
    const remaining = document.querySelectorAll(".tab-btn");
    if (remaining.length > 0)
      activateTab(remaining[remaining.length - 1].dataset.tabId, remaining[remaining.length - 1]);
  }
}

function reindexColumnMap(map, lo, hi) {
  const newMap = {};
  const removed = hi - lo + 1;
  Object.keys(map).forEach((k) => {
    const col = Number(k);
    if (col < lo) newMap[col] = map[col];
    else if (col > hi) newMap[col - removed] = map[col];
  });
  return newMap;
}

// Map variant of reindexColumnMap, the strip/consensus stat caches are Maps keyed by column
function reindexColumnCacheMap(map, lo, hi) {
  const removed = hi - lo + 1;
  const entries = Array.from(map.entries());
  map.clear();
  for (const [k, v] of entries) {
    if (k < lo) map.set(k, v);
    else if (k > hi) map.set(k - removed, v);
  }
}

//  Sequence names panel (virtualized): only rows near the viewport exist in
//  the DOM. A spacer provides the scroll range; a translated window holds the
//  visible slice. Reordering is data-driven (by record id), so the DOM slice
//  is disposable and re-rendered from tabState.records

function buildNamesPanel(namesPanel, tabState, onStructureChanged) {
  if (!namesPanel._vstate) {
    const spacer = document.createElement("div");
    spacer.className = "names-spacer";
    const win = document.createElement("div");
    win.className = "names-window";
    namesPanel.innerHTML = "";
    namesPanel.appendChild(spacer);
    namesPanel.appendChild(win);
    namesPanel._vstate = { spacer, win, firstRow: -1, lastRow: -1, renderedH: 0 };
    namesPanel.addEventListener("scroll", () => renderNameWindow(namesPanel, tabState, onStructureChanged), {
      passive: true
    });
  }
  renderNameWindow(namesPanel, tabState, onStructureChanged, true); // structure may have changed so always rebuild the slice
}

function renderNameWindow(namesPanel, tabState, onStructureChanged, force) {
  const st = namesPanel._vstate;
  if (!st) return;
  const h = cellDimsFor(tabState.fontSize).h;
  const rows = tabState.records.length;
  // The names panel uses the same capped physical row span as the alignment
  // panel. `vScrollScale` belongs to the tab; store it on the panel so this
  // standalone helper does not need a new positional argument.
  // same capped physical span as the alignment panel
  const scale = namesPanel._vScrollScale || 1;
  const realHeight = rows * h;
  st.spacer.style.height = Math.max(1, realHeight * scale) + "px";

  // the same max-normalized physical->logical mapping realVScroll uses -
  // NOT a linear divide-by-scale (they differ by the viewport height)
  const physicalMax = Math.max(0, realHeight * scale - namesPanel.clientHeight);
  const realMax = Math.max(0, realHeight - namesPanel.clientHeight);
  const physicalTop = namesPanel.scrollTop;
  const logicalScrollTop = physicalMax > 0 ? (physicalTop * realMax) / physicalMax : 0;

  const MARGIN = 8; // rows of buffer above and below the viewport
  const first = Math.max(0, Math.floor(logicalScrollTop / h - MARGIN));
  const last = Math.min(rows, Math.ceil((logicalScrollTop + namesPanel.clientHeight) / h + MARGIN));
  if (!force && first === st.firstRow && last === st.lastRow && h === st.renderedH) return; // nothing moved
  st.firstRow = first;
  st.lastRow = last;
  st.renderedH = h;

  // place the window so logical row `first` sits at the same viewport offset
  // the canvas is drawing, reduces to the original `first * h` when scale === 1
  st.win.style.transform = `translateY(${physicalTop + first * h - logicalScrollTop}px)`;
  st.win.innerHTML = "";
  for (let i = first; i < last; i++)
    st.win.appendChild(buildNameRow(tabState.records[i], tabState, onStructureChanged));
}

function buildNameRow(record, tabState, onStructureChanged) {
  const row = document.createElement("div");
  row.className = "name-row";
  row.dataset.id = record.id;
  row.style.height = cellDimsFor(tabState.fontSize).h + "px"; // fixed: full logical row height
  const text = document.createElement("span");
  text.className = "name-text";
  text.textContent = record.header;
  text.title = "Double-click to rename";
  text.addEventListener("dblclick", (e) => {
    e.stopPropagation();
    text.contentEditable = "true";
    text.focus();
    document.execCommand("selectAll", false, null);
  });
  text.addEventListener("blur", () => {
    text.contentEditable = "false";
    record.header = text.textContent.trim() || record.header;
  });
  text.addEventListener("keydown", (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      text.blur();
    }
  });

  const btns = document.createElement("span");
  btns.className = "row-btns";

  const idxOf = () => tabState.records.findIndex((r) => r.id === record.id);

  const upBtn = mkBtn("\u25B2", "Move up", () => {
    const i = idxOf();
    if (i > 0) {
      const tmp = tabState.records[i - 1];
      tabState.records[i - 1] = tabState.records[i];
      tabState.records[i] = tmp;
      onStructureChanged({ keepPlane: true, keepConsensus: true }); // pure permutation, stats survive
    }
  });
  const topBtn = mkBtn("\u2912", "Move to top", () => {
    const i = idxOf();
    if (i > 0) {
      const [item] = tabState.records.splice(i, 1);
      tabState.records.unshift(item);
      onStructureChanged({ keepPlane: true, keepConsensus: true });
    }
  });
  const bottomBtn = mkBtn("\u2913", "Move to bottom", () => {
    const i = idxOf();
    if (i >= 0 && i < tabState.records.length - 1) {
      const [item] = tabState.records.splice(i, 1);
      tabState.records.push(item);
      onStructureChanged({ keepPlane: true, keepConsensus: true });
    }
  });
  const deleteBtn = mkBtn("🗑", "Delete sequence", () => {
    if (tabState.records.length <= 1) {
      showLastRowModal("sequence");
      return;
    }
    showConfirmDeleteModal(`sequence "${record.header}"`, () => {
      const i = idxOf();
      if (i === -1) return;
      const prog = showProgressOverlay("Deleting sequence");
      prog.setLabel("Updating column statistics…");
      setTimeout(() => {
        try {
          adjustLoadPlaneForRows(tabState, [tabState.records[i]], -1); // plane stays exact, no stale stats
          tabState.records.splice(i, 1);
          onStructureChanged({ keepPlane: true }); // plane was adjusted exactly, don't null it
          prog.setLabel("Recomputing consensus…");
          setTimeout(() => {
            try {
              recomputeSimpleConsensus(tabState, prog); // re-bakes Simple consensus post-delete
              if (tabState._repaintConsensus) tabState._repaintConsensus();
            } finally {
              prog.close();
            }
          }, 30);
        } catch (e) {
          prog.close();
          throw e;
        }
      }, 30);
    });
  });
  deleteBtn.classList.add("delete-btn");

  btns.append(upBtn, topBtn, bottomBtn, deleteBtn);
  row.append(text, btns);
  return row;
}

// Save-as-project format chooser: .blim (binary, memory-efficient) or
// .slim (text, backwards-compatible with the original SlimShadey)
function showSaveProjectModal(onBlim, onSlim) {
  const overlay = document.createElement("div");
  overlay.className = "modal-overlay";
  const box = document.createElement("div");
  box.className = "modal-box shade-modal";
  box.innerHTML = "<h3>Save project</h3>";

  const msgRow = document.createElement("div");
  msgRow.className = "shade-row";
  msgRow.textContent =
    "Save as .blim (memory-efficient, new format) or .slim (backwards compatible with the original SlimShadey)?";
  box.appendChild(msgRow);

  const btnRow = document.createElement("div");
  btnRow.className = "shade-row";

  const blimBtn = document.createElement("button");
  blimBtn.textContent = ".blim";
  blimBtn.className = "modal-close-btn";
  blimBtn.title = "Binary format, far smaller files";
  blimBtn.addEventListener("click", () => {
    overlay.remove();
    onBlim();
  });

  const slimBtn = document.createElement("button");
  slimBtn.textContent = ".slim";
  slimBtn.className = "modal-close-btn";
  slimBtn.title = "Text format, readable by the original SlimShadey";
  slimBtn.addEventListener("click", () => {
    overlay.remove();
    onSlim();
  });

  const cancelBtn = document.createElement("button");
  cancelBtn.textContent = "Cancel";
  cancelBtn.className = "modal-close-btn";
  cancelBtn.addEventListener("click", () => overlay.remove());

  btnRow.append(blimBtn, slimBtn, cancelBtn);
  box.appendChild(btnRow);
  overlay.appendChild(box);
  overlay.addEventListener("click", (e) => {
    if (e.target === overlay) overlay.remove(); // clicking outside means cancel
  });
  document.body.appendChild(overlay);
}

//Confirm-delete modal\
function showConfirmDeleteModal(label, onConfirm) {
  const overlay = document.createElement("div");
  overlay.className = "modal-overlay";
  const box = document.createElement("div");
  box.className = "modal-box shade-modal";
  box.innerHTML = `<h3>Delete ${label}?</h3>`;

  const msgRow = document.createElement("div");
  msgRow.className = "shade-row";
  msgRow.textContent = "This cannot be undone.";
  box.appendChild(msgRow);

  const btnRow = document.createElement("div");
  btnRow.className = "shade-row";

  const deleteBtn = document.createElement("button");
  deleteBtn.textContent = "Delete";
  deleteBtn.className = "modal-close-btn";
  deleteBtn.addEventListener("click", () => {
    overlay.remove();
    onConfirm();
  });

  const cancelBtn = document.createElement("button");
  cancelBtn.textContent = "Cancel";
  cancelBtn.className = "modal-close-btn";
  cancelBtn.addEventListener("click", () => overlay.remove());

  btnRow.append(deleteBtn, cancelBtn);
  box.appendChild(btnRow);

  overlay.appendChild(box);
  overlay.addEventListener("click", (e) => {
    if (e.target === overlay) overlay.remove(); // again, clicking outside = cancel
  });
  document.body.appendChild(overlay);
}

// Last-row delete rejection modal
function showLastRowModal(kind) {
  const label = kind === "annotation" ? "annotation row" : "sequence";
  const overlay = document.createElement("div");
  overlay.className = "modal-overlay";
  const box = document.createElement("div");
  box.className = "modal-box shade-modal";
  box.innerHTML = `<h3>Can't delete</h3>`;

  const msgRow = document.createElement("div");
  msgRow.className = "shade-row";
  msgRow.textContent = `This is your last ${label}, and at least one is required. It can't be deleted.`;
  box.appendChild(msgRow);

  const btnRow = document.createElement("div");
  btnRow.className = "shade-row";
  const okBtn = document.createElement("button");
  okBtn.textContent = "OK";
  okBtn.className = "modal-close-btn";
  okBtn.addEventListener("click", () => overlay.remove());
  btnRow.appendChild(okBtn);
  box.appendChild(btnRow);

  overlay.appendChild(box);
  overlay.addEventListener("click", (e) => {
    if (e.target === overlay) overlay.remove();
  });
  document.body.appendChild(overlay);
}

function mkBtn(label, title, onClick) {
  const b = document.createElement("span");
  b.className = "row-btn";
  b.textContent = label;
  b.title = title;
  b.addEventListener("click", (e) => {
    e.stopPropagation();
    onClick();
  });
  return b;
}

