// Examples: auto-discovered from GitHub repo
const EXAMPLE_REPO = { owner: "as2654", repo: "SlimShadey-Examples", branch: "main" };
const EXAMPLE_EXTS = [".blim", ".slim", ".mm", ".fasta", ".fa", ".faa", ".fna"];
